const PRODUCT_DUPLICATE_DATA_KEYS=['id','sku','name','category','brand','type','product_type','wh','warehouse_id','stock','cost','price','unit','expiry','_catalogExpiry','_revision'];
function additionalData(record,duplicateKeys){
  const data={...(record&&typeof record==='object'?record:{})};
  duplicateKeys.forEach(key=>delete data[key]);
  return data;
}
function productToRow(p){
  const data=additionalData(p,PRODUCT_DUPLICATE_DATA_KEYS);
  return { id:p.id, sku:p.sku||null, name:p.name||'', category:p.category||null, brand:p.brand||null, product_type:p.type||null, warehouse_id:p.wh||null, cost:Number(p.cost)||0, price:Number(p.price)||0, unit:p.unit||null, data };
}
// Existing product metadata must never carry a possibly stale stock value from
// another browser tab. Stock is changed only through the atomic stock RPCs.
function productMetadataToRow(p){
  const data=additionalData(p,PRODUCT_DUPLICATE_DATA_KEYS);
  return { id:p.id, sku:p.sku||null, name:p.name||'', category:p.category||null, brand:p.brand||null, product_type:p.type||null, warehouse_id:p.wh||null, cost:Number(p.cost)||0, price:Number(p.price)||0, unit:p.unit||null, data, revision:Number(p._revision)||0 };
}
function rowToProduct(row){
  row=row||{};
  const data=row.data&&typeof row.data==='object'?row.data:{};
  const hasValue=value=>value!==null&&value!==undefined&&value!=='';
  const textValue=(key,flatValue,fallback='')=>Object.hasOwn(data,key)&&hasValue(data[key])?data[key]:(hasValue(flatValue)?flatValue:fallback);
  const numberValue=(key,flatValue)=>{
    if(Object.hasOwn(data,key)&&hasValue(data[key])&&Number.isFinite(Number(data[key]))) return Number(data[key]);
    return Number.isFinite(Number(flatValue))?Number(flatValue):0;
  };
  // The data fallback is read-only compatibility for a device that opens an
  // old row before the cleanup migration. New writes always remove these keys.
  return {
    ...data,
    id:row.id,
    sku:textValue('sku',row.sku),
    name:textValue('name',row.name),
    category:textValue('category',row.category),
    brand:textValue('brand',row.brand),
    type:textValue('type',row.product_type,'stock'),
    wh:Object.hasOwn(data,'wh')&&hasValue(data.wh)?data.wh:(row.warehouse_id??null),
    stock:0,
    cost:numberValue('cost',row.cost),
    price:numberValue('price',row.price),
    unit:textValue('unit',row.unit),
    _revision:Number(row.revision)||1,
    _catalogExpiry:textValue('expiry',null),
  };
}
function warehouseToRow(w){ return { id:w.id, name:w.name||'', data:additionalData(w,['id','name']) }; }
function rowToWarehouse(row){ return { ...(row.data||{}), id:row.id, name:row.name }; }
function contactToRow(c){
  const types=Array.isArray(c.types)?c.types:[];
  const type=types.includes('customer')&&types.includes('supplier')?'both':(types.includes('supplier')?'supplier':'customer');
  return { id:c.id, type, name:c.name||'', phone:c.phone||null, data:additionalData(c,['id','type','types','name','phone']) };
}
function rowToContact(row){
  const types=row.type==='both'?['customer','supplier']:[row.type==='supplier'?'supplier':'customer'];
  return { ...(row.data||{}), id:row.id, name:row.name, phone:row.phone||'', types };
}
function salesRepToRow(r){ return { id:r.id, name:r.name||'', data:additionalData(r,['id','name']) }; }
function rowToSalesRep(row){ return { ...(row.data||{}), id:row.id, name:row.name }; }

// Supabase/PostgREST caps SELECT results at a fixed row count per request
// (1,000 by default) unless the query is explicitly paginated with
// .range(). Every "fetch every row" query in this app was a plain
// select('*') with no range -- silently invisible until a table actually
// grew past that cap. Confirmed the hard way: products (2,800+ real rows)
// loaded into the app as only its first 1,000. This helper pages through
// in fixed-size chunks and concatenates the results, so callers always get
// every row regardless of table size. Pass a function that builds a FRESH
// query each call (not a query object itself), since .range() is chained
// onto a new builder per page.
async function fetchAllRows(buildQuery){
  const pageSize=1000;
  let from=0,allRows=[];
  while(true){
    const {data,error}=await buildQuery().range(from,from+pageSize-1);
    if(error) return {data:null,error};
    allRows=allRows.concat(data||[]);
    if(!data||data.length<pageSize) break;
    from+=pageSize;
  }
  return {data:allRows,error:null};
}

// Product reads use a lightweight manifest (id + updated_at) after the first
// successful load. A normal refresh therefore downloads full JSON only for
// products that were added or changed, while ids missing from the manifest
// remove products deleted by another device. The first load remains a safe
// full download so an incomplete/stale local cache is never trusted blindly.
// v4 forces one safe full reload after fixing the product loader's accidental
// second rowToProduct() pass, which discarded JSON-only metadata such as every
// barcode collection, extra units and expiry dates from the device cache.
const PRODUCT_MANIFEST_STORAGE_KEY='pepos_product_manifest_v4';
const PRODUCT_MANIFEST_VERSION=4;
const PRODUCT_CACHE_DB_NAME='pepos-product-cache';
const PRODUCT_CACHE_DB_VERSION=1;
const PRODUCT_CACHE_PRODUCTS_STORE='products';
const PRODUCT_CACHE_META_STORE='meta';
const PRODUCT_CACHE_MANIFEST_KEY='product-manifest-v4';
const PRODUCT_CACHE_DIRTY_KEY='product-dirty-operations-v1';
let productCacheDbPromise=null;
let indexedProductCacheReady=false;
let cachedProductManifest=null;
let productCacheFingerprints=new Map();
let productCacheWriteChain=Promise.resolve();
let productDirtyOperations=new Map();
let legacyWorkspaceProducts=null;
function productManifestVersions(rows){
  const versions={};
  (rows||[]).forEach(row=>{ versions[String(row.id)]=String(row.updated_at||''); });
  return versions;
}
function readProductManifestCache(){
  const cached=cachedProductManifest;
  if(!cached||cached.version!==PRODUCT_MANIFEST_VERSION||!cached.versions||typeof cached.versions!=='object') return null;
  return cached;
}
function normalizeProductDirtyOperations(value){
  const entries=value&&typeof value.entries==='function'?[...value.entries()]:(Array.isArray(value)?value:Object.entries(value&&typeof value==='object'?value:{}));
  const normalized=new Map();
  entries.forEach(([id,operation])=>{
    const key=String(id||'').trim();
    if(key&&['insert','update','delete'].includes(operation)) normalized.set(key,operation);
  });
  return normalized;
}
function productDirtyOperationsValue(value=productDirtyOperations){
  return Object.fromEntries([...normalizeProductDirtyOperations(value).entries()].sort((a,b)=>a[0].localeCompare(b[0],undefined,{numeric:true})));
}
function markProductChangesDirty({insertedIds=[],updatedIds=[],deletedIds=[]}={}){
  insertedIds.forEach(id=>{ if(id!==null&&id!==undefined) productDirtyOperations.set(String(id),'insert'); });
  updatedIds.forEach(id=>{
    if(id===null||id===undefined) return;
    const key=String(id);
    if(productDirtyOperations.get(key)!=='insert') productDirtyOperations.set(key,'update');
  });
  deletedIds.forEach(id=>{
    if(id===null||id===undefined) return;
    const key=String(id);
    if(productDirtyOperations.get(key)==='insert') productDirtyOperations.delete(key);
    else productDirtyOperations.set(key,'delete');
  });
}
function idbRequest(request){
  return new Promise((resolve,reject)=>{
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>reject(request.error||new Error('IndexedDB request failed'));
  });
}
function idbTransactionDone(transaction){
  return new Promise((resolve,reject)=>{
    transaction.oncomplete=()=>resolve();
    transaction.onerror=()=>reject(transaction.error||new Error('IndexedDB transaction failed'));
    transaction.onabort=()=>reject(transaction.error||new Error('IndexedDB transaction aborted'));
  });
}
function openProductCacheDb(){
  if(productCacheDbPromise) return productCacheDbPromise;
  if(!window.indexedDB) return Promise.reject(new Error('IndexedDB unavailable'));
  productCacheDbPromise=new Promise((resolve,reject)=>{
    const request=indexedDB.open(PRODUCT_CACHE_DB_NAME,PRODUCT_CACHE_DB_VERSION);
    request.onupgradeneeded=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(PRODUCT_CACHE_PRODUCTS_STORE)) db.createObjectStore(PRODUCT_CACHE_PRODUCTS_STORE,{keyPath:'id'});
      if(!db.objectStoreNames.contains(PRODUCT_CACHE_META_STORE)) db.createObjectStore(PRODUCT_CACHE_META_STORE,{keyPath:'key'});
    };
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>{ productCacheDbPromise=null; reject(request.error||new Error('เปิดแคชสินค้าไม่สำเร็จ')); };
  });
  return productCacheDbPromise;
}
function validLegacyProductManifest(){
  try{
    const cached=JSON.parse(localStorage.getItem(PRODUCT_MANIFEST_STORAGE_KEY)||'null');
    return cached&&cached.version===PRODUCT_MANIFEST_VERSION&&cached.versions&&typeof cached.versions==='object'?cached:null;
  }catch(error){ return null; }
}
async function loadProductCacheFromIndexedDB(){
  try{
    const db=await openProductCacheDb();
    const transaction=db.transaction([PRODUCT_CACHE_PRODUCTS_STORE,PRODUCT_CACHE_META_STORE],'readonly');
    const transactionDone=idbTransactionDone(transaction);
    const productRowsPromise=idbRequest(transaction.objectStore(PRODUCT_CACHE_PRODUCTS_STORE).getAll());
    const manifestPromise=idbRequest(transaction.objectStore(PRODUCT_CACHE_META_STORE).get(PRODUCT_CACHE_MANIFEST_KEY));
    const dirtyOperationsPromise=idbRequest(transaction.objectStore(PRODUCT_CACHE_META_STORE).get(PRODUCT_CACHE_DIRTY_KEY));
    const [productRows,manifestRow,dirtyOperationsRow]=await Promise.all([productRowsPromise,manifestPromise,dirtyOperationsPromise]);
    await transactionDone;
    productDirtyOperations=normalizeProductDirtyOperations(dirtyOperationsRow?.value);
    if(Array.isArray(productRows)&&productRows.length){
      products=productRows;
      productCacheFingerprints=new Map(productRows.map(product=>[String(product.id),JSON.stringify(product)]));
    }else if(Array.isArray(legacyWorkspaceProducts)&&legacyWorkspaceProducts.length){
      products=legacyWorkspaceProducts;
    }
    cachedProductManifest=manifestRow?.value||validLegacyProductManifest();
    indexedProductCacheReady=Array.isArray(productRows)&&productRows.length>0;
    if(!indexedProductCacheReady&&Array.isArray(legacyWorkspaceProducts)&&legacyWorkspaceProducts.length){
      await persistProductsToIndexedDB(legacyWorkspaceProducts,true);
      indexedProductCacheReady=true;
    }
    rebuildProductLookupMaps();
    refreshDataCounters();
    return indexedProductCacheReady;
  }catch(error){
    indexedProductCacheReady=false;
    console.warn('ไม่สามารถโหลดแคชสินค้าจาก IndexedDB ได้ ระบบจะดึงข้อมูลจากเซิร์ฟเวอร์',error);
    return false;
  }
}
async function saveProductManifestCache(rows){
  const manifest={
    version:PRODUCT_MANIFEST_VERSION,
    savedAt:new Date().toISOString(),
    versions:productManifestVersions(rows),
  };
  try{
    const db=await openProductCacheDb();
    const transaction=db.transaction(PRODUCT_CACHE_META_STORE,'readwrite');
    const transactionDone=idbTransactionDone(transaction);
    transaction.objectStore(PRODUCT_CACHE_META_STORE).put({key:PRODUCT_CACHE_MANIFEST_KEY,value:manifest});
    await transactionDone;
    cachedProductManifest=manifest;
    localStorage.removeItem(PRODUCT_MANIFEST_STORAGE_KEY);
    return true;
  }catch(error){ console.warn('ไม่สามารถบันทึกสารบัญแคชสินค้าใน IndexedDB ได้',error); return false; }
}
function persistProductsToIndexedDB(productRows=products,removeMissing=true,dirtyOperations=productDirtyOperations){
  const rows=JSON.parse(JSON.stringify(Array.isArray(productRows)?productRows:[]));
  const dirtyValue=productDirtyOperationsValue(dirtyOperations);
  const write=async()=>{
    try{
      const db=await openProductCacheDb();
      const nextFingerprints=new Map(rows.map(product=>[String(product.id),JSON.stringify(product)]));
      const changed=rows.filter(product=>productCacheFingerprints.get(String(product.id))!==nextFingerprints.get(String(product.id)));
      const deleted=removeMissing?[...productCacheFingerprints.keys()].filter(id=>!nextFingerprints.has(id)):[];
      const transaction=db.transaction([PRODUCT_CACHE_PRODUCTS_STORE,PRODUCT_CACHE_META_STORE],'readwrite');
      const transactionDone=idbTransactionDone(transaction);
      const store=transaction.objectStore(PRODUCT_CACHE_PRODUCTS_STORE);
      changed.forEach(product=>store.put(product));
      deleted.forEach(id=>store.delete(Number.isFinite(Number(id))?Number(id):id));
      transaction.objectStore(PRODUCT_CACHE_META_STORE).put({key:PRODUCT_CACHE_DIRTY_KEY,value:dirtyValue});
      await transactionDone;
      productCacheFingerprints=nextFingerprints;
      indexedProductCacheReady=rows.length>0;
      return true;
    }catch(error){
      console.warn('ไม่สามารถบันทึกแคชสินค้าใน IndexedDB ได้',error);
      return false;
    }
  };
  productCacheWriteChain=productCacheWriteChain.then(write,write);
  return productCacheWriteChain;
}
function persistProductChangesToIndexedDB(changes={},dirtyOperations=productDirtyOperations){
  const changedIds=new Set([...(changes.insertedIds||[]),...(changes.updatedIds||[])].map(String));
  const deletedIds=[...(changes.deletedIds||[])].map(String);
  const rows=JSON.parse(JSON.stringify((products||[]).filter(product=>changedIds.has(String(product.id)))));
  const dirtyValue=productDirtyOperationsValue(dirtyOperations);
  const write=async()=>{
    try{
      const db=await openProductCacheDb();
      const transaction=db.transaction([PRODUCT_CACHE_PRODUCTS_STORE,PRODUCT_CACHE_META_STORE],'readwrite');
      const transactionDone=idbTransactionDone(transaction);
      const store=transaction.objectStore(PRODUCT_CACHE_PRODUCTS_STORE);
      rows.forEach(product=>store.put(product));
      deletedIds.forEach(id=>store.delete(Number.isFinite(Number(id))?Number(id):id));
      transaction.objectStore(PRODUCT_CACHE_META_STORE).put({key:PRODUCT_CACHE_DIRTY_KEY,value:dirtyValue});
      await transactionDone;
      rows.forEach(product=>productCacheFingerprints.set(String(product.id),JSON.stringify(product)));
      deletedIds.forEach(id=>productCacheFingerprints.delete(id));
      indexedProductCacheReady=productCacheFingerprints.size>0;
      return true;
    }catch(error){
      console.warn('ไม่สามารถบันทึกการเปลี่ยนแปลงสินค้าใน IndexedDB ได้',error);
      return false;
    }
  };
  productCacheWriteChain=productCacheWriteChain.then(write,write);
  return productCacheWriteChain;
}
async function clearProductIndexedCache(){
  try{
    const db=productCacheDbPromise?await productCacheDbPromise:null;
    db?.close();
  }catch(error){}
  productCacheDbPromise=null;
  productCacheWriteChain=Promise.resolve();
  indexedProductCacheReady=false;
  cachedProductManifest=null;
  productCacheFingerprints=new Map();
  productDirtyOperations=new Map();
  if(!window.indexedDB) return;
  try{ await idbRequest(indexedDB.deleteDatabase(PRODUCT_CACHE_DB_NAME)); }
  catch(error){ console.warn('ล้างแคชสินค้าใน IndexedDB ไม่สำเร็จ',error); }
}
function planProductManifestSync(localProducts,cachedManifest,manifestRows,hasWorkspaceCache,dirtyOperations=new Map()){
  const cacheUsable=!!hasWorkspaceCache&&!!cachedManifest&&cachedManifest.version===PRODUCT_MANIFEST_VERSION&&cachedManifest.versions&&typeof cachedManifest.versions==='object';
  if(!cacheUsable) return {fullReload:true,changedIds:[],deletedIds:[]};
  const dirty=normalizeProductDirtyOperations(dirtyOperations);
  const remoteVersions=productManifestVersions(manifestRows);
  const localIds=new Set((localProducts||[]).map(product=>String(product.id)));
  const changedIds=(manifestRows||[]).filter(row=>!dirty.has(String(row.id))&&(!localIds.has(String(row.id))||cachedManifest.versions[String(row.id)]!==String(row.updated_at||''))).map(row=>row.id);
  const remoteIds=new Set(Object.keys(remoteVersions));
  const deletedIds=(localProducts||[]).map(product=>product.id).filter(id=>!dirty.has(String(id))&&!remoteIds.has(String(id)));
  return {fullReload:false,changedIds,deletedIds};
}
async function fetchProductManifestRows(){
  const pageSize=1000;
  let lastId=null,allRows=[];
  while(true){
    let query=sb.from('products').select('id,updated_at,revision').order('id',{ascending:true}).limit(pageSize);
    if(lastId!==null) query=query.gt('id',lastId);
    const {data,error}=await query;
    if(error) return {data:null,error};
    const rows=data||[];
    allRows=allRows.concat(rows);
    if(rows.length<pageSize) break;
    lastId=rows[rows.length-1].id;
  }
  return {data:allRows,error:null};
}
async function fetchAllProductRows(){
  const pageSize=1000;
  let lastId=null,allRows=[];
  while(true){
    let query=sb.from('products').select('*').order('id',{ascending:true}).limit(pageSize);
    if(lastId!==null) query=query.gt('id',lastId);
    const {data,error}=await query;
    if(error) return {data:null,error};
    const rows=data||[];
    allRows=allRows.concat(rows);
    if(rows.length<pageSize) break;
    lastId=rows[rows.length-1].id;
  }
  return {data:allRows,error:null};
}
async function fetchProductRowsByIds(ids){
  const allRows=[];
  for(let i=0;i<ids.length;i+=200){
    const {data,error}=await sb.from('products').select('*').in('id',ids.slice(i,i+200));
    if(error) return {data:null,error};
    allRows.push(...(data||[]));
  }
  return {data:allRows,error:null};
}
function reconcileProductDirtyOperationsWithManifest(manifestRows){
  const remoteIds=new Set((manifestRows||[]).map(row=>String(row.id)));
  let changed=false;
  for(const [id,operation] of productDirtyOperations){
    if(operation==='update'&&!remoteIds.has(id)){ productDirtyOperations.set(id,'insert'); changed=true; }
    else if(operation==='delete'&&!remoteIds.has(id)){ productDirtyOperations.delete(id); changed=true; }
  }
  return changed;
}
function mergeRemoteProductsWithDirtyLocal(remoteProducts,localProducts=products,dirtyOperations=productDirtyOperations){
  const dirty=normalizeProductDirtyOperations(dirtyOperations);
  const localById=new Map((localProducts||[]).map(product=>[String(product.id),product]));
  const merged=(remoteProducts||[]).filter(product=>dirty.get(String(product.id))!=='delete');
  const mergedById=new Map(merged.map((product,index)=>[String(product.id),index]));
  for(const [id,operation] of dirty){
    if(operation==='delete') continue;
    const local=localById.get(id);
    if(!local) continue;
    const index=mergedById.get(id);
    if(index===undefined){ mergedById.set(id,merged.length); merged.push(local); }
    else merged[index]=local;
  }
  return merged.sort((a,b)=>(Number(a.id)||0)-(Number(b.id)||0));
}
async function loadProductRowsFromSupabase(){
  const {data:manifestRows,error:manifestError}=await fetchProductManifestRows();
  if(manifestError) return {data:null,error:manifestError};
  reconcileProductDirtyOperationsWithManifest(manifestRows);
  const cachedManifest=readProductManifestCache();
  const plan=planProductManifestSync(products,cachedManifest,manifestRows,indexedProductCacheReady,productDirtyOperations);
  let loadedProducts;
  if(plan.fullReload){
    const {data,error}=await fetchAllProductRows();
    if(error) return {data:null,error};
    loadedProducts=mergeRemoteProductsWithDirtyLocal((data||[]).map(rowToProduct));
  }else{
    const {data:changedRows,error}=await fetchProductRowsByIds(plan.changedIds);
    if(error) return {data:null,error};
    const changedIds=new Set(plan.changedIds.map(String));
    const deletedIds=new Set(plan.deletedIds.map(String));
    loadedProducts=(products||[]).filter(product=>!changedIds.has(String(product.id))&&!deletedIds.has(String(product.id)));
    loadedProducts.push(...(changedRows||[]).map(rowToProduct));
    loadedProducts=mergeRemoteProductsWithDirtyLocal(loadedProducts);
  }
  const productRowsPersisted=await persistProductsToIndexedDB(loadedProducts,true);
  if(productRowsPersisted) await saveProductManifestCache(manifestRows);
  return {data:loadedProducts,error:null};
}

// Content-hash guard: snapshots make the incremental synchronizer send only changed rows.
// Failed writes are intentionally not acknowledged so a later save retries them.
let lastSyncedSnapshot={};
const syncedTableRows={};
function tableSnapshot(localArray,toRow){
  const snapshot=new Map();
  (localArray||[]).forEach(item=>{
    const row=toRow(item);
    snapshot.set(String(row.id),JSON.stringify(row));
  });
  return snapshot;
}
function seedTableSnapshot(table,localArray,toRow){ syncedTableRows[table]=tableSnapshot(localArray,toRow); }
function seedProductSyncSnapshot(localProducts=products,dirtyOperations=productDirtyOperations){
  const snapshot=tableSnapshot(localProducts,productMetadataToRow);
  for(const [id,operation] of normalizeProductDirtyOperations(dirtyOperations)){
    if(operation==='delete') snapshot.set(id,'__dirty_remote_product__');
    else snapshot.delete(id);
  }
  syncedTableRows.products=snapshot;
}
async function clearAcknowledgedProductDirtyOperations(ids,expectedOperations){
  const expected=normalizeProductDirtyOperations(expectedOperations);
  const removable=(ids||[]).map(String).filter(id=>productDirtyOperations.get(id)===expected.get(id));
  if(!removable.length) return true;
  const next=new Map(productDirtyOperations);
  removable.forEach(id=>next.delete(id));
  const persisted=await persistProductsToIndexedDB(products,true,next);
  if(!persisted) return false;
  removable.forEach(id=>{ if(productDirtyOperations.get(id)===expected.get(id)) productDirtyOperations.delete(id); });
  return true;
}
async function upsertRowsInChunks(table,rows){
  for(let i=0;i<rows.length;i+=200){
    const {error}=await sb.from(table).upsert(rows.slice(i,i+200));
    if(error) return error;
  }
  return null;
}
function productCreateTokenFromRow(row){
  return String(row?.data?._clientCreateToken||'').trim();
}
function canonicalProductInsertValue(value){
  if(Array.isArray(value)) return value.map(canonicalProductInsertValue);
  if(value&&typeof value==='object'){
    const canonical={};
    Object.keys(value).sort().forEach(key=>{ if(value[key]!==undefined) canonical[key]=canonicalProductInsertValue(value[key]); });
    return canonical;
  }
  return typeof value==='number'&&!Number.isFinite(value)?null:value;
}
function productInsertMetadataRow(row){
  const data={...(row?.data||{})};
  delete data.stock;
  delete data._catalogExpiry;
  return {
    id:row?.id,
    sku:row?.sku??null,
    name:row?.name||'',
    category:row?.category??null,
    brand:row?.brand??null,
    product_type:row?.product_type??null,
    warehouse_id:row?.warehouse_id??null,
    cost:Number(row?.cost)||0,
    price:Number(row?.price)||0,
    unit:row?.unit??null,
    data,
  };
}
function canonicalProductInsertSignature(row){
  return JSON.stringify(canonicalProductInsertValue(productInsertMetadataRow(row)));
}
function productInsertCollisionError(id){
  const error=new Error(`รหัสอ้างอิงสินค้า ${id} ชนกับสินค้าคนละรายการ ระบบหยุดซิงก์เพื่อป้องกันข้อมูลถูกเขียนทับ`);
  error.code='PRODUCT_ID_COLLISION';
  error.productId=id;
  return error;
}
async function verifyProductInsertChunk(table,rows){
  const ids=(rows||[]).map(row=>row.id);
  const {data,error}=await sb.from(table).select('id,sku,name,category,brand,product_type,warehouse_id,cost,price,unit,data').in('id',ids);
  if(error) return {error,missing:[],metadataMismatches:[]};
  const remoteById=new Map((data||[]).map(row=>[String(row.id),row]));
  const missing=[],metadataMismatches=[];
  for(const row of rows||[]){
    const remote=remoteById.get(String(row.id));
    if(!remote){ missing.push(row); continue; }
    const localToken=productCreateTokenFromRow(row);
    const remoteToken=productCreateTokenFromRow(remote);
    // The token is immutable creation identity. Other fields may legitimately
    // change after the first insert (stock RPC, metadata edit) before retry.
    if(!localToken||!remoteToken||localToken!==remoteToken){
      return {error:productInsertCollisionError(row.id),missing:[],metadataMismatches:[]};
    }
    if(canonicalProductInsertSignature(row)!==canonicalProductInsertSignature(remote)) metadataMismatches.push(row);
  }
  return {error:null,missing,metadataMismatches};
}
async function updateVerifiedProductMetadataRows(rows){
  for(let i=0;i<rows.length;i+=12){
    const results=await Promise.all(rows.slice(i,i+12).map(async row=>{
      const token=productCreateTokenFromRow(row);
      if(!token) return {error:productInsertCollisionError(row.id)};
      const {id,...changes}=productInsertMetadataRow(row);
      const {data,error}=await sb.from('products').update(changes).eq('id',id).contains('data',{_clientCreateToken:token}).select('id');
      if(error) return {error};
      const matched=(data||[]).filter(saved=>String(saved.id)===String(id));
      return matched.length===1?{error:null}:{error:productInsertCollisionError(id)};
    }));
    const failed=results.find(result=>result.error);
    if(failed) return failed.error;
  }
  return null;
}
async function insertRowsInChunks(table,rows){
  for(let i=0;i<rows.length;i+=200){
    let pending=rows.slice(i,i+200),lastError=null;
    for(let attempt=0;attempt<3&&pending.length;attempt++){
      const {error}=await sb.from(table).insert(pending);
      if(!error){ pending=[]; break; }
      lastError=error;
      if(table!=='products') return error;
      const verification=await verifyProductInsertChunk(table,pending);
      if(verification.error) return verification.error;
      if(verification.metadataMismatches.length){
        // The id/token pair proves this is our own earlier create. Reapply only
        // metadata (never stock) so edits made before the retry are not lost.
        const metadataError=await updateVerifiedProductMetadataRows(verification.metadataMismatches);
        if(metadataError) return metadataError;
      }
      // A previous ambiguous request may have committed only the earlier rows
      // or chunks. Retry only rows that are still absent; never update matches.
      pending=verification.missing;
    }
    if(pending.length) return lastError||new Error('บันทึกสินค้าใหม่ไม่สำเร็จ');
  }
  return null;
}
async function updateProductMetadataInChunks(productRows){
  for(let i=0;i<productRows.length;i+=12){
    const batch=productRows.slice(i,i+12);
    const results=await Promise.all(batch.map(product=>{
      const row=productMetadataToRow(product),{id,revision,...changes}=row;
      return sb.from('products').update(changes).eq('id',id).eq('revision',revision).select('id,revision').maybeSingle();
    }));
    const failed=results.find(result=>result.error);
    if(failed) return failed.error;
    const conflictIndex=results.findIndex(result=>!result.data);
    if(conflictIndex>=0){ const error=new Error(`สินค้า ${batch[conflictIndex]?.sku||batch[conflictIndex]?.id} ถูกแก้ไขจากอีกเครื่องแล้ว`); error.code='REVISION_CONFLICT'; return error; }
    results.forEach((result,index)=>{ batch[index]._revision=Number(result.data?.revision)||Number(batch[index]._revision)||1; });
  }
  return null;
}
// Sync only rows changed since this device last loaded/saved them. Deletions
// are derived from that same baseline, never by comparing against every remote
// id, so a stale device cannot delete records created by another device.
async function upsertAndPrune(table,localArray,toRow){
  const previous=syncedTableRows[table]||new Map();
  const current=tableSnapshot(localArray,toRow);
  const changed=(localArray||[]).filter(item=>{
    const row=toRow(item);
    return previous.get(String(row.id))!==JSON.stringify(row);
  });
  const deleted=[...previous.keys()].filter(id=>!current.has(id));
  if(!changed.length&&!deleted.length) return true;
  if(changed.length){
    const error=await upsertRowsInChunks(table,changed.map(toRow));
    if(error){ console.warn('sync '+table,error); return false; }
  }
  if(deleted.length){
    const {error}=await sb.from(table).delete().in('id',deleted);
    if(error){ console.warn('sync delete '+table,error); return false; }
  }
  syncedTableRows[table]=current;
  return true;
}
async function syncWarehousesIncrementally(){
  const table='warehouses';
  const previous=syncedTableRows[table]||new Map();
  const current=tableSnapshot(warehouses,warehouseToRow);
  const changed=warehouses.filter(warehouse=>{
    const row=warehouseToRow(warehouse);
    return previous.get(String(row.id))!==JSON.stringify(row);
  });
  const deleted=[...previous.keys()].filter(id=>!current.has(id));
  if(!changed.length&&!deleted.length) return true;
  for(const warehouse of changed){
    const row=warehouseToRow(warehouse);
    const {error}=await sb.rpc('owner_upsert_warehouse',{
      p_id:Number(row.id)||null,
      p_name:row.name,
      p_data:row.data,
    });
    if(error){ console.warn('sync warehouse',row.id,error); return false; }
  }
  for(const id of deleted){
    const {error}=await sb.rpc('owner_delete_warehouse',{p_id:Number(id)});
    if(error){ console.warn('sync delete warehouse',id,error); return false; }
  }
  syncedTableRows[table]=current;
  return true;
}
async function prepareProductInsertCandidatesForSync(previous){
  // Older caches can contain a product that predates dirty-operation tracking.
  // Give every row that this sync will classify as a new insert the same durable
  // identity marker as an explicitly dirty insert before any network request.
  const implicitInsertCandidates=products.filter(product=>{
    const id=String(product.id);
    return !productDirtyOperations.has(id)&&!previous.has(id);
  });
  const tokenlessDirtyInserts=products.filter(product=>productDirtyOperations.get(String(product.id))==='insert'&&!String(product._clientCreateToken||'').trim());
  const insertPreparationProducts=[...new Map([...implicitInsertCandidates,...tokenlessDirtyInserts].map(product=>[String(product.id),product])).values()];
  if(insertPreparationProducts.length){
    const operationAssignments=implicitInsertCandidates.map(product=>({id:String(product.id),hadOperation:productDirtyOperations.has(String(product.id)),previousOperation:productDirtyOperations.get(String(product.id))}));
    operationAssignments.forEach(entry=>{ productDirtyOperations.set(entry.id,'insert'); });
    const tokenAssignments=insertPreparationProducts.filter(product=>!String(product._clientCreateToken||'').trim()).map(product=>({product,hadToken:Object.hasOwn(product,'_clientCreateToken'),previousToken:product._clientCreateToken,token:generateProductCreateToken()}));
    tokenAssignments.forEach(entry=>{ entry.product._clientCreateToken=entry.token; });
    const tokenCacheSaved=await persistProductChangesToIndexedDB({updatedIds:insertPreparationProducts.map(product=>product.id)});
    if(!tokenCacheSaved){
      tokenAssignments.forEach(entry=>{ if(entry.hadToken) entry.product._clientCreateToken=entry.previousToken; else delete entry.product._clientCreateToken; });
      operationAssignments.forEach(entry=>{ if(entry.hadOperation) productDirtyOperations.set(entry.id,entry.previousOperation); else productDirtyOperations.delete(entry.id); });
      console.warn('sync new products: creation token cache failed');
      return false;
    }
  }
  return true;
}
async function syncProductsIncrementally(){
  const table='products';
  const previous=syncedTableRows[table]||new Map();
  if(!await prepareProductInsertCandidatesForSync(previous)) return false;
  const current=tableSnapshot(products,productMetadataToRow);
  const dirtyAtStart=new Map(productDirtyOperations);
  const changed=products.filter(product=>previous.get(String(product.id))!==JSON.stringify(productMetadataToRow(product)));
  const inserted=changed.filter(product=>dirtyAtStart.get(String(product.id))==='insert'||(!dirtyAtStart.has(String(product.id))&&!previous.has(String(product.id))));
  const updated=changed.filter(product=>dirtyAtStart.get(String(product.id))==='update'||(!dirtyAtStart.has(String(product.id))&&previous.has(String(product.id))));
  const deleted=[...previous.keys()].filter(id=>!current.has(id));
  if(updated.length){
    const error=await updateProductMetadataInChunks(updated);
    if(error){ console.warn('sync products',error); return false; }
  }
  if(inserted.length){
    // New client-generated ids must fail closed on a primary-key collision.
    // Upsert would silently replace the product created by another device.
    const error=await insertRowsInChunks(table,inserted.map(productToRow));
    if(error){ console.warn('sync new products',error); return false; }
    const {data:insertedRevisions,error:revisionError}=await sb.from('products').select('id,revision').in('id',inserted.map(product=>product.id));
    if(revisionError){ console.warn('load new product revisions',revisionError); return false; }
    const revisions=new Map((insertedRevisions||[]).map(row=>[String(row.id),Number(row.revision)||1]));
    inserted.forEach(product=>{ product._revision=revisions.get(String(product.id))||1; });
  }
  if(deleted.length){
    const {error}=await sb.from(table).delete().in('id',deleted);
    if(error){ console.warn('sync delete products',error); return false; }
  }
  syncedTableRows[table]=tableSnapshot(products,productMetadataToRow);
  const acknowledgedDirtyIds=[];
  for(const [id,operation] of dirtyAtStart){
    const unchangedOperation=productDirtyOperations.get(id)===operation;
    const unchangedProduct=operation==='delete'?!current.has(id):current.get(id)===JSON.stringify(productMetadataToRow(products.find(product=>String(product.id)===id)||{}));
    if(unchangedOperation&&unchangedProduct) acknowledgedDirtyIds.push(id);
  }
  if(acknowledgedDirtyIds.length){
    const dirtyStatePersisted=await clearAcknowledgedProductDirtyOperations(acknowledgedDirtyIds,dirtyAtStart);
    if(!dirtyStatePersisted){ seedProductSyncSnapshot(products,productDirtyOperations); return false; }
  }
  return true;
}

let coreSyncInFlight=false, coreSyncPending=false;
// Simple id+data-jsonb document tables (Milestone 5) -- same shape, no extra
// reporting columns needed for these yet.
function docToRow(doc){ const {createdByUserId,_revision,...data}=doc||{}; return {id:doc?.id,data,revision:Number(_revision)||0}; }
function rowToDoc(row){ return { ...(row.data||{}), id:row.id, _revision:Number(row.revision)||1, ...(row.created_by?{createdByUserId:String(row.created_by)}:{}) }; }
const DOC_TABLES = [
  ['quotations', ()=>quotations, v=>{quotations=v;}],
  ['invoices_ar', ()=>invoicesAR, v=>{invoicesAR=v;}],
  ['credit_notes', ()=>creditNotes, v=>{creditNotes=v;}],
  ['purchase_orders', ()=>purchaseOrders, v=>{purchaseOrders=v;}],
  ['goods_receipts', ()=>goodsReceipts, v=>{goodsReceipts=v;}],
  ['product_exchanges', ()=>productExchanges, v=>{productExchanges=v;}],
  ['purchase_orders_full', ()=>purchaseOrdersFull, v=>{purchaseOrdersFull=v;}],
  ['product_returns', ()=>productReturns, v=>{productReturns=v;}],
  ['transfers', ()=>transfers, v=>{transfers=v;}],
  ['standalone_tax_invoices', ()=>standaloneTaxInvoices, v=>{standaloneTaxInvoices=v;}],
];
async function syncCoreDataToSupabase(){
  if(!currentProfile) return;
  if(await adoptRemoteMaintenanceEpoch()){
    await loadCoreDataFromSupabase(); await loadSalesHistoryFromSupabase(); await loadCashShiftsFromSupabase(); await loadInspectionListsFromSupabase(); await loadPromotionsFromSupabase(); await loadFavoritesFromSupabase();
    render(); return;
  }
  if(coreSyncInFlight){ coreSyncPending=true; return; }
  coreSyncInFlight=true;
  setSyncUiState('syncing');
  do{
    coreSyncPending=false;
    try{
      if(loggedInUser()?.owner===true){
        if(!await syncWarehousesIncrementally()) throw new Error('ซิงก์คลังสินค้าไม่สำเร็จ');
        if(!await syncProductsIncrementally()) throw new Error('ซิงก์สินค้าไม่สำเร็จ');
        if(!await upsertAndPrune('contacts',contacts,contactToRow)) throw new Error('ซิงก์สมุดรายชื่อไม่สำเร็จ');
        if(!await upsertAndPrune('sales_representatives',salesRepresentatives,salesRepToRow)) throw new Error('ซิงก์รายชื่อผู้แทนไม่สำเร็จ');
        for(const [table,getArr] of DOC_TABLES){ await syncRevisionedDocuments(table,getArr()); }
      }
      await syncInspectionListsToSupabase();
      setSyncUiState('synced',0);
    }catch(e){
      console.warn('sync core data failed',e);
      setSyncUiState(navigator.onLine?'error':'offline',syncUiErrorCount+1);
      reportClientEvent({operation:'sync_core_data',message:e?.message||'ซิงก์ข้อมูลไม่สำเร็จ',context:{tab:currentTab}});
      if(e?.code==='REVISION_CONFLICT') showToast(e.message,'danger-top');
    }
  }while(coreSyncPending);
  coreSyncInFlight=false;
}

// Stock never travels through product metadata sync. It is written atomically
// to inventory_balances/inventory_lots and then reflected into the local UI.
async function adjustProductStockOnSupabase(productId,delta,warehouseId=activeWarehouseId){
  if(!currentProfile||!delta) return;
  const targetWarehouseId=Number(warehouseId)||Number(activeWarehouseId);
  if(!targetWarehouseId){ console.warn('adjust product stock: warehouse is required',productId); return; }
  try{
    const {data,error}=await sb.rpc('adjust_inventory_stock',{p_product_id:productId,p_warehouse_id:targetWarehouseId,p_delta:delta});
    if(error){ console.warn('adjust product stock',productId,error); return; }
    updateInventoryBalanceLocal(productId,targetWarehouseId,Number(data)||0);
    await loadInventoryLotsFromSupabase();
  }
  catch(e){ console.warn('adjust product stock failed',productId,e); }
}
async function setProductStockOnSupabase(productId,newStock,warehouseId=activeWarehouseId){
  if(!currentProfile) return;
  const targetWarehouseId=Number(warehouseId)||Number(activeWarehouseId);
  if(!targetWarehouseId){ console.warn('set product stock: warehouse is required',productId); return; }
  try{
    const {data,error}=await sb.rpc('set_inventory_stock',{p_product_id:productId,p_warehouse_id:targetWarehouseId,p_stock:Number(newStock)||0});
    if(error){ console.warn('set product stock',productId,error); return; }
    updateInventoryBalanceLocal(productId,targetWarehouseId,Number(data)||0);
    await loadInventoryLotsFromSupabase();
  }
  catch(e){ console.warn('set product stock failed',productId,e); }
}
async function setProductExpiryOnSupabase(productId,newExpiry,warehouseId=activeWarehouseId){
  if(!currentProfile) return false;
  const targetWarehouseId=Number(warehouseId)||Number(activeWarehouseId);
  if(!targetWarehouseId){ console.warn('set product expiry: warehouse is required',productId); return false; }
  try{
    const normalizedExpiry=String(newExpiry||'').trim()||null;
    const {data,error}=await sb.rpc('set_inventory_expiry',{p_product_id:productId,p_warehouse_id:targetWarehouseId,p_expiry:normalizedExpiry});
    if(error){ console.warn('set product expiry',productId,error); return false; }
    updateInventoryBalanceLocal(productId,targetWarehouseId,warehouseStock(productId,targetWarehouseId),data||'');
    await loadInventoryLotsFromSupabase();
    return true;
  }catch(error){ console.warn('set product expiry failed',productId,error); return false; }
}
async function transferProductStockOnSupabase(productId,fromWarehouseId,toWarehouseId,quantity){
  if(!currentProfile||!quantity) return null;
  try{
    const data=await runStockOperation('transfer_inventory_stock',{productId,fromWarehouseId:Number(fromWarehouseId),toWarehouseId:Number(toWarehouseId),quantity:Number(quantity)});
    updateInventoryBalanceLocal(productId,fromWarehouseId,Number(data?.fromStock)||0);
    updateInventoryBalanceLocal(productId,toWarehouseId,Number(data?.toStock)||0);
    await loadInventoryLotsFromSupabase();
    return data;
  }catch(error){ console.warn('transfer product stock failed',productId,error); return null; }
}
// ----- Business settings sync -----
// Single object (not a list), stored as one row in the generic key/value
// `settings` table (key='business') that was already part of the original
// schema but never actually used until now. Uses the same lastSyncedSnapshot
// content-hash guard as upsertAndPrune() so an unrelated render doesn't
// re-upload it needlessly.
async function syncBusinessSettingsToSupabase(){
  if(!currentProfile){ businessSettingsSyncState='local'; return false; }
  const snapshot=JSON.stringify(businessSettings);
  if(lastSyncedSnapshot.business_settings===snapshot){ businessSettingsSyncState='synced'; return true; }
  businessSettingsSyncState='syncing';
  businessSettingsSyncError='';
  try{
    const {error}=await sb.rpc('owner_set_setting',{p_key:'business',p_value:businessSettings});
    if(error) throw error;
    lastSyncedSnapshot.business_settings=snapshot;
    businessSettingsSyncState='synced';
    businessSettingsLastSyncedAt=new Date().toISOString();
    return true;
  }catch(e){
    console.warn('sync business settings failed',e);
    businessSettingsSyncState='error';
    businessSettingsSyncError=e?.message||'เชื่อมต่อ Supabase ไม่สำเร็จ';
    return false;
  }
}
function applyBusinessSettings(value){
  businessSettings={...businessSettings,...(value&&typeof value==='object'?value:{})};
  STORE_INFO.name=String(businessSettings.name||'');
  STORE_INFO.address=String(businessSettings.address||'');
  STORE_INFO.taxId=String(businessSettings.taxId||'');
  STORE_INFO.phone=businessPrimaryPhone(businessSettings);
  STORE_INFO.website=String(businessSettings.website||'');
  STORE_INFO.branch=businessTaxBranchLabel(businessSettings);
}
async function loadBusinessSettingsFromSupabase(){
  try{
    const {data,error}=await sb.from('settings').select('value').eq('key','business').maybeSingle();
    if(error){ console.warn('load business settings',error); return; }
    if(data&&data.value&&typeof data.value==='object'){
      applyBusinessSettings(data.value);
      lastSyncedSnapshot.business_settings=JSON.stringify(businessSettings);
      businessSettingsSyncState='synced';
      businessSettingsLastSyncedAt=new Date().toISOString();
    }else{
      await syncBusinessSettingsToSupabase(); // first time ever: seed Supabase from whatever's local right now
    }
  }catch(e){ console.warn('load business settings failed',e); }
}

// ----- Document number prefixes sync -----
// Another single object, same settings(key,value) table as business settings.
async function syncDocumentPrefixesToSupabase(){
  if(!currentProfile) return;
  const snapshot=JSON.stringify(documentPrefixes);
  if(lastSyncedSnapshot.document_prefixes===snapshot) return;
  try{
    const {error}=await sb.rpc('owner_set_setting',{p_key:'document_prefixes',p_value:documentPrefixes});
    if(error){ console.warn('sync document prefixes',error); return; }
    lastSyncedSnapshot.document_prefixes=snapshot;
  }catch(e){ console.warn('sync document prefixes failed',e); }
}
async function loadDocumentPrefixesFromSupabase(){
  try{
    const {data,error}=await sb.from('settings').select('value').eq('key','document_prefixes').maybeSingle();
    if(error){ console.warn('load document prefixes',error); return; }
    if(data&&data.value&&typeof data.value==='object'){
      Object.keys(DEFAULT_DOCUMENT_PREFIXES).forEach(key=>{
        documentPrefixes[key]=normalizeDocumentPrefix(data.value[key],DEFAULT_DOCUMENT_PREFIXES[key]);
      });
      lastSyncedSnapshot.document_prefixes=JSON.stringify(documentPrefixes);
    }else{
      await syncDocumentPrefixesToSupabase(); // first time ever: seed Supabase from whatever's local right now
    }
  }catch(e){ console.warn('load document prefixes failed',e); }
}

// ----- Saved product inspection lists sync -----
// Each list is its own row so two devices can add/edit different lists without
// replacing the entire shared array in settings.
function inspectionListToRow(list){ return {id:list.id,data:list}; }
async function syncInspectionListsToSupabase(){
  if(!currentProfile) return false;
  try{ await upsertAndPrune('inspection_lists',inspectionLists,inspectionListToRow); return true; }
  catch(e){ console.warn('sync inspection lists failed',e); return false; }
}
async function loadInspectionListsFromSupabase(){
  try{
    const {data,error}=await fetchAllRows(()=>sb.from('inspection_lists').select('*').order('id'));
    if(error){ console.warn('load inspection lists',error); return; }
    if((data||[]).length){
      inspectionLists=normalizeInspectionLists(data.map(row=>({...(row.data||{}),id:row.id})));
      seedTableSnapshot('inspection_lists',inspectionLists,inspectionListToRow);
    }else{
      // One-time migration from the former settings-array storage.
      const {data:legacy}=await sb.from('settings').select('value').eq('key','inspection_lists').maybeSingle();
      if(legacy&&Array.isArray(legacy.value)&&legacy.value.length) inspectionLists=normalizeInspectionLists(legacy.value);
      seedTableSnapshot('inspection_lists',[],inspectionListToRow);
      if(inspectionLists.length) await syncInspectionListsToSupabase();
    }
    refreshDataCounters();
  }catch(e){ console.warn('load inspection lists failed',e); }
}

// ----- Shared favorites sync (one store-wide list for every signed-in user) -----
// The table keeps user_id only as the last editor. product_id is the shared
// primary key, so every account loads and edits the same ordered list.
async function syncFavoritesToSupabase(){
  if(!currentProfile) return;
  favorites=normalizeFavorites(favorites);
  const snapshot=JSON.stringify(favorites);
  if(lastSyncedSnapshot.favorites===snapshot) return;
  try{
    const rows=favorites.map((entry,position)=>({user_id:currentProfile.id,product_id:entry.pid,unit:entry.unit||'',position}));
    if(rows.length){ const {error}=await sb.from('favorites').upsert(rows,{onConflict:'product_id'}); if(error){ console.warn('sync favorites',error); return; } }
    const {data:existing}=await fetchAllRows(()=>sb.from('favorites').select('product_id'));
    const localIds=new Set(favorites.map(entry=>entry.pid));
    const del=(existing||[]).filter(r=>!localIds.has(r.product_id)).map(r=>r.product_id);
    if(del.length) await sb.from('favorites').delete().in('product_id',del);
    lastSyncedSnapshot.favorites=snapshot;
  }catch(e){ console.warn('sync favorites failed',e); }
}
async function loadFavoritesFromSupabase(){
  if(!currentProfile) return;
  try{
    const {data,error}=await fetchAllRows(()=>sb.from('favorites').select('product_id,unit,position,created_at').order('position').order('created_at'));
    if(error){ console.warn('load favorites',error); return; }
    favorites=normalizeFavorites((data||[]).map(row=>({pid:row.product_id,unit:row.unit})));
    lastSyncedSnapshot.favorites=JSON.stringify(favorites);
  }catch(e){ console.warn('load favorites failed',e); }
}

async function loadCoreDataFromSupabase(){
  try{
    await adoptRemoteMaintenanceEpoch();
    const [{data:whRows,error:whErr},{data:prodRows,error:prodErr},{data:contactRows,error:contactErr},{data:repRows,error:repErr},{data:accessRows,error:accessErr},{data:permissionRows,error:permissionErr},{data:balanceRows,error:balanceErr},{data:lotRows,error:lotErr}]=await Promise.all([
      fetchAllRows(()=>sb.from('warehouses').select('*').order('id')),
      loadProductRowsFromSupabase(),
      fetchAllRows(()=>sb.from('contacts').select('*').order('id')),
      fetchAllRows(()=>sb.from('sales_representatives').select('*').order('id')),
      fetchAllRows(()=>sb.from('profile_warehouse_access').select('*').eq('user_id',currentProfile.id).order('warehouse_id')),
      fetchAllRows(()=>sb.from('profile_page_permissions').select('*').eq('user_id',currentProfile.id).order('page_key')),
      fetchAllRows(()=>sb.from('inventory_balances').select('warehouse_id,product_id,stock,expiry,updated_at').order('warehouse_id').order('product_id')),
      fetchAllRows(()=>sb.from('inventory_lots').select('id,product_id,warehouse_id,internal_code,manufacturer_lot,expiry_date,quantity_base,unit_cost_base,received_at,source_type,source_id,status,updated_at').gt('quantity_base',0).order('warehouse_id').order('product_id').order('expiry_date',{ascending:true,nullsFirst:false}).order('received_at')),
    ]);
    // Keep the current app usable during the short rolling-deploy window before
    // the page-permission migration reaches Supabase. Every other core table is
    // still mandatory; only this newly introduced table has a legacy fallback.
    const permissionTablePending=permissionErr&&['42P01','PGRST205'].includes(String(permissionErr.code||''));
    if(whErr||prodErr||contactErr||repErr||accessErr||(permissionErr&&!permissionTablePending)||balanceErr||lotErr){ console.warn('load core data',whErr||prodErr||contactErr||repErr||accessErr||permissionErr||balanceErr||lotErr); return; }
    const docResults=await Promise.all(DOC_TABLES.map(([table])=>fetchAllRows(()=>sb.from(table).select('*').order('id',{ascending:false}))));
    const docErr=docResults.find(r=>r.error);
    if(docErr){ console.warn('load core data (docs)',docErr.error); return; }
    const allEmpty=(whRows||[]).length===0&&(prodRows||[]).length===0&&(contactRows||[]).length===0&&(repRows||[]).length===0&&docResults.every(r=>(r.data||[]).length===0);
    if(allEmpty){
      // Import only a real saved workspace. Never push the built-in demo rows
      // into an intentionally empty production database.
      if(indexedProductCacheReady&&products.length){ await syncCoreDataToSupabase(); return; }
      warehouses=[]; products=[]; contacts=[]; salesRepresentatives=[];
      DOC_TABLES.forEach(([_table,_getArr,setArr])=>setArr([]));
    }
    warehouses=(whRows||[]).map(rowToWarehouse);
    // loadProductRowsFromSupabase() already returns normalized product objects.
    // Mapping them as database rows a second time strips JSON-only fields such
    // as barcode, extraBarcodes, vendorBarcodes, units and expiry.
    products=prodRows||[];
    rebuildProductLookupMaps();
    warehouseAccessRows=accessRows||[];
    pagePermissionRows=permissionTablePending?[]:(permissionRows||[]);
    inventoryBalanceRows=(balanceRows||[]).map(row=>({...row,warehouse_id:Number(row.warehouse_id),product_id:Number(row.product_id),stock:Number(row.stock)||0}));
    inventoryLotRows=(lotRows||[]).map(normalizeInventoryLotRow);
    rebuildInventoryBalanceMap();
    rebuildInventoryLotMap();
    restoreActiveWarehouseSelection();
    contacts=(contactRows||[]).map(rowToContact);
    salesRepresentatives=(repRows||[]).map(rowToSalesRep);
    refreshCategoryBrandUnitLists();
    DOC_TABLES.forEach(([table,_getArr,setArr],i)=>{
      const rows=docResults[i].data||[];
      setArr(rows.map(rowToDoc));
    });
    const goodsReceiptsBeforeNormalization=JSON.stringify(goodsReceipts);
    goodsReceipts=normalizeGoodsReceiptDocuments(goodsReceipts);
    const goodsReceiptsMigrated=goodsReceiptsBeforeNormalization!==JSON.stringify(goodsReceipts);
    // Seed the change-detection cache to match what we just loaded, so the
    // next debounced sync doesn't immediately re-upload everything again
    // merely because it hasn't "seen" this exact snapshot before.
    seedTableSnapshot('warehouses',warehouses,warehouseToRow);
    seedProductSyncSnapshot(products,productDirtyOperations);
    seedTableSnapshot('contacts',contacts,contactToRow);
    seedTableSnapshot('sales_representatives',salesRepresentatives,salesRepToRow);
    DOC_TABLES.forEach(([table,getArr])=>{
      if(table==='goods_receipts'&&goodsReceiptsMigrated) delete syncedTableRows[table];
      else seedTableSnapshot(table,getArr(),docToRow);
    });
    nextWarehouseId=maxArrayValue(warehouses,w=>(Number(w.id)||0)+1,1);
    nextContactId=maxArrayValue(contacts,c=>(Number(c.id)||0)+1,1);
    nextSalesRepresentativeId=maxArrayValue(salesRepresentatives,r=>(Number(r.id)||0)+1,1);
    refreshDataCounters();
    if(productDirtyOperations.size) scheduleSupabaseCoreSync();
  }catch(e){ console.warn('load core data failed',e); }
}

// ----- Sales history sync -----
// Posted sales intentionally keep an immutable document body in `data` for
// reprints, voids, and audits. The flat columns are reporting indexes, while
// the JSON body remains the authoritative historic document and is therefore
// not treated like duplicate mutable master data.
function saleToRow(s){
  let saleTime=null;
  if(s.time){ const d=new Date(String(s.time).replace(' ','T')); if(!isNaN(d.getTime())) saleTime=d.toISOString(); }
  const memberName=s.member?(typeof s.member==='object'?(s.member.name||''):String(s.member)):null;
  return { id:s.id, ref:s.ref||null, sale_date:s.date||null, sale_time:saleTime, cashier:s.cashier||null, member:memberName, status:s.status||'done', pay_method:s.payMethod||null, discount:Number(s.discount)||0, vat:Number(s.vat)||0, fee:Number(s.fee)||0, cost_total:Number(s.costTotal)||0, gross_profit:Number(s.grossProfit)||0, cash_received:Number(s.cashReceived)||0, cash_change:Number(s.cashChange)||0, total:Number(s.total)||0, data:s };
}
function rowToSale(row){
  const fallback={
    id:row.id,ref:row.ref||'',date:row.sale_date||'',time:row.sale_time||'',cashier:row.cashier||'',member:row.member||null,
    status:row.status||'done',payMethod:row.pay_method||'',discount:Number(row.discount)||0,vat:Number(row.vat)||0,
    fee:Number(row.fee)||0,costTotal:Number(row.cost_total)||0,grossProfit:Number(row.gross_profit)||0,
    cashReceived:Number(row.cash_received)||0,cashChange:Number(row.cash_change)||0,total:Number(row.total)||0,
    cashShiftId:row.cash_shift_id||'',voidShiftId:row.void_shift_id||'',
  };
  return {...fallback,...(row.data||{}),id:row.id};
}

async function loadSalesHistoryFromSupabase(){
  try{
    const { data:rows, error } = await fetchAllRows(()=>sb.from('sales').select('*').order('sale_date',{ascending:false}));
    if(error){ console.warn('load sales',error); return; }
    if((rows||[]).length===0){ salesHistory=[]; return; }
    salesHistory=rows.map(rowToSale);
    invoiceCounter=maxArrayValue(salesHistory,s=>(Number(String(s.id||'').replace(/\D/g,''))||0)+1,1000);
  }catch(e){ console.warn('load sales failed',e); }
}

function normalizeCashShiftRow(row){
  if(!row) return null;
  return {
    id:String(row.id||''),shiftNo:String(row.shift_no||''),warehouseId:Number(row.warehouse_id)||0,
    openedBy:String(row.opened_by||''),openedByName:String(row.opened_by_name||''),openedAt:String(row.opened_at||''),
    openingCash:Number(row.opening_cash)||0,status:row.status==='closed'?'closed':'open',
    closedBy:String(row.closed_by||''),closedByName:String(row.closed_by_name||''),closedAt:String(row.closed_at||''),
    grossSales:Number(row.gross_sales)||0,refunds:Number(row.refunds)||0,netSales:Number(row.net_sales)||0,
    cashSales:Number(row.cash_sales)||0,cashRefunds:Number(row.cash_refunds)||0,expectedCash:Number(row.expected_cash)||0,
    countedCash:row.counted_cash===null?null:Number(row.counted_cash)||0,variance:row.variance===null?null:Number(row.variance)||0,
    saleCount:Number(row.sale_count)||0,refundCount:Number(row.refund_count)||0,
    paymentSummary:row.payment_summary&&typeof row.payment_summary==='object'?row.payment_summary:{},closeReason:String(row.close_reason||'')
  };
}
async function loadCashShiftsFromSupabase(){
  if(!currentProfile||!activeWarehouseId||isAllWarehousesMode()){
    cashShifts=[]; currentCashShift=null; return false;
  }
  try{
    const {data,error}=await sb.from('cash_shifts').select('*').eq('warehouse_id',Number(activeWarehouseId)).order('opened_at',{ascending:false}).limit(100);
    if(error) throw error;
    cashShifts=(data||[]).map(normalizeCashShiftRow).filter(Boolean);
    currentCashShift=cashShifts.find(shift=>shift.status==='open'&&shift.openedBy===String(currentProfile.id))||null;
    return true;
  }catch(error){
    console.warn('load cash shifts failed',error);
    cashShifts=[]; currentCashShift=null; return false;
  }
}
