function activePurchaseDraft(){
  if(currentTab==='taxinvoice'&&editingTaxInvoiceSaleId==='manual-new') return taxInvoiceDraft;
  if(currentTab==='quotation'&&editingQuotationId!==null) return taxInvoiceDraft;
  return docDraft(currentDocKind());
}

function documentProductPool(){
  return activeProducts();
}

function documentProductMatches(query){
  const q=String(query||'').trim().toLowerCase();
  if(!q) return [];
  return documentProductPool().filter(p=>
    (p.name||'').toLowerCase().includes(q) ||
    (p.sku||'').toLowerCase().includes(q) ||
    (p.barcode||'').toLowerCase().includes(q) ||
    (p.extraBarcodes||[]).some(code=>(code||'').toLowerCase().includes(q)) ||
    (p.vendorBarcodes||[]).some(v=>(v.code||'').toLowerCase().includes(q)) ||
    (p.units||[]).some(u=>(u.barcode||'').toLowerCase().includes(q))
  );
}

function exactDocumentProduct(query){
  const q=String(query||'').trim().toLowerCase();
  if(!q) return null;
  const productPool=documentProductPool();
  // ให้บาร์โค้ดหลักและรหัสสินค้ามีสิทธิ์ก่อนบาร์โค้ดของหน่วยย่อย
  let product=productPool.find(p=>(p.barcode||'').toLowerCase()===q || (p.sku||'').toLowerCase()===q || (p.vendorBarcodes||[]).some(v=>(v.code||'').toLowerCase()===q));
  if(product) return {product,unit:product.unit};
  for(const p of productPool){
    const extra=extraBarcodeEntries(p).find(item=>String(item.code).toLowerCase()===q);
    if(extra) return {product:p,unit:extraBarcodeAvailableUnits(p).includes(extra.unit)?extra.unit:p.unit};
  }
  for(const p of productPool){
    const unit=(p.units||[]).find(u=>(u.barcode||'').toLowerCase()===q);
    if(unit) return {product:p,unit:unit.sub||p.unit};
  }
  return null;
}

function addDocumentScannedProduct(productId,unitName){
  if(currentTab==='transfer'&&editingTransferId!==null){
    syncTransferFromDOM();
    const draft=activeTransferDraft();
    const product=products.find(p=>p.id===productId);
    if(!draft||!product) return;
    const sourceId=Number(draft.fromId)||0;
    const unit=unitName||product.unit;
    const cost=transferUnitOptions(product).find(option=>option.name===unit)?.cost||0;
    const existing=draft.items.find(item=>Number(item.productId)===Number(product.id)&&(item.unit||product.unit)===unit);
    if(existing){
      existing.qty=(Number(existing.qty)||0)+1;
    }else{
      const item={lineId:transferLineCounter++,productId:product.id,name:product.name,qty:1,unit,cost};
      const blank=draft.items.find(row=>!row.name);
      if(blank) Object.assign(blank,item,{lineId:blank.lineId||item.lineId}); else draft.items.push(item);
    }
    render();
    setTimeout(()=>document.getElementById('docProductScanner')?.focus(),0);
    return;
  }
  syncPOFromDOM();
  if((currentTab==='taxinvoice'||currentTab==='quotation')&&typeof syncTaxInvoiceDraftFromDOM==='function') syncTaxInvoiceDraftFromDOM();
  const draft=activePurchaseDraft();
  const product=products.find(p=>p.id===productId);
  if(!draft||!product) return;
  const unit=unitName||product.unit;
  const existing=currentTab==='productreturn'?null:draft.items.find(item=>item.name===product.name && (item.unit||product.unit)===unit);
  if(existing){
    existing.qty=(Number(existing.qty)||0)+1;
  }else{
    const saleUnit=productUnitOptions(product).find(option=>option.name===unit);
    const item={productId:product.id,name:product.name,qty:1,unit,price:(currentTab==='goodsreceipt'||currentTab==='purchaseorder2'||currentTab==='productreturn')?'':(currentTab==='taxinvoice'||currentTab==='quotation')?(saleUnit?.price??product.price):0,...(currentTab==='goodsreceipt'?{lineId:String(Date.now()),warehouseId:Number(draft.warehouseId)||0}:currentTab==='productreturn'?{lineId:String(Date.now()),warehouseId:Number(draft.warehouseId)||0,lotId:null,lotNumber:'',expiry:''}:{})};
    const blank=draft.items.find(row=>!row.name);
    if(blank) Object.assign(blank,item); else draft.items.push(item);
  }
  render();
  setTimeout(()=>document.getElementById('docProductScanner')?.focus(),0);
}

function renderDocumentScanResults(query){
  const box=document.getElementById('docScanResults');
  if(!box) return;
  const q=String(query||'').trim();
  if(!q){ box.innerHTML=''; box.hidden=true; return; }
  const matches=documentProductMatches(q).slice(0,8);
  box.innerHTML=matches.length?matches.map(p=>{
    const exactUnit=(p.units||[]).find(u=>(u.barcode||'').toLowerCase()===q.toLowerCase());
    const extraUnit=extraBarcodeEntries(p).find(item=>String(item.code).toLowerCase()===q.toLowerCase())?.unit;
    const unit=exactUnit?.sub||(extraBarcodeAvailableUnits(p).includes(extraUnit)?extraUnit:p.unit);
    const unitNames=[p.unit,...(p.units||[]).map(u=>u.sub).filter(Boolean)].join(', ');
    return `<button type="button" class="doc-scan-result" data-pid="${escapeHtml(Number(p.id))}" data-unit="${escapeHtml(unit)}"><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.sku||'-')} · บาร์โค้ด ${escapeHtml(p.barcode||'-')} · หน่วย ${escapeHtml(unitNames)}</small></span><span class="stock">คงเหลือ ${escapeHtml(stockInLargestUnit(p))}</span></button>`;
  }).join(''):`<div class="doc-scan-empty">ไม่พบสินค้า “${escapeHtml(q)}”</div>`;
  box.hidden=false;
  box.querySelectorAll('.doc-scan-result').forEach(btn=>{
    btn.addEventListener('mousedown',e=>e.preventDefault());
    btn.addEventListener('click',()=>addDocumentScannedProduct(Number(btn.dataset.pid),btn.dataset.unit));
  });
}

function bindDocumentProductScanner(){
  const input=document.getElementById('docProductScanner');
  const box=document.getElementById('docScanResults');
  if(!input||!box) return;
  input.addEventListener('input',()=>renderDocumentScanResults(input.value));
  input.addEventListener('focus',()=>{ if(input.value.trim()) renderDocumentScanResults(input.value); });
  input.addEventListener('keydown',e=>{
    if(e.key==='Escape'){ box.hidden=true; input.value=''; return; }
    if(e.key!=='Enter') return;
    e.preventDefault();
    const query=input.value.trim(); if(!query) return;
    const exact=exactDocumentProduct(query);
    if(exact){ addDocumentScannedProduct(exact.product.id,exact.unit); return; }
    const first=documentProductMatches(query)[0];
    if(first) addDocumentScannedProduct(first.id,first.unit);
  });
  input.addEventListener('blur',()=>setTimeout(()=>{ box.hidden=true; },140));
}

function bindPOItemEvents(){
  document.querySelectorAll('#poItemRows .po-item-row').forEach(row=>{
    const unitSel=row.querySelector('.poi_unit'); if(unitSel) unitSel.addEventListener('change', ()=>{ recalcPORow(row); if(currentTab==='productreturn'){ syncPOFromDOM(); render(); } });
    ['.poi_qty','.poi_price'].forEach(sel=>{ const el=row.querySelector(sel); if(el) el.addEventListener('input', ()=>recalcPORow(row)); });
    const expiry=row.querySelector('.poi_expiry'); if(expiry) expiry.addEventListener('input',()=>{ expiry.value=formatDMYInput(expiry.value); });
    const returnLot=row.querySelector('.poi_return_lot'); if(returnLot) returnLot.addEventListener('change',()=>{ syncPOFromDOM(); render(); });
    row.querySelector('.poi_del').addEventListener('click', ()=>{ syncPOFromDOM(); if((currentTab==='taxinvoice'||currentTab==='quotation')&&typeof syncTaxInvoiceDraftFromDOM==='function') syncTaxInvoiceDraftFromDOM(); const draft=activePurchaseDraft(); draft.items.splice([...document.querySelectorAll('#poItemRows .po-item-row')].indexOf(row),1); if(draft.items.length===0) draft.items=[{name:'',qty:1,unit:'',price:''}]; render(); });
  });
}

function savePORepresentativeFromPO(){
  syncPOFromDOM();
  const draft=activePurchaseDraft();
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const name=get('po_rep_name');
  if(!name){ showToast('กรุณากรอกชื่อผู้แทน'); document.getElementById('po_rep_name').focus(); return; }
  const duplicate=salesRepresentatives.find(rep=>rep.name===name && rep.id!==poRepresentativeEditorId);
  if(duplicate){ showToast('มีชื่อผู้แทนนี้อยู่แล้ว'); document.getElementById('po_rep_name').focus(); return; }
  const data={name,phone:get('po_rep_phone'),line:get('po_rep_line'),note:get('po_rep_note')};
  if(poRepresentativeEditorId==='new'){
    salesRepresentatives.push({id:nextSalesRepresentativeId++,...data});
    showToast(`เพิ่มผู้แทน “${name}” แล้ว`);
  }else{
    const rep=salesRepresentatives.find(x=>x.id===poRepresentativeEditorId);
    if(rep){
      const oldName=rep.name;
      Object.assign(rep,data);
      purchaseOrders.forEach(doc=>{ if(doc.supplier===oldName) doc.supplier=name; });
    }
    showToast(`บันทึกข้อมูลผู้แทน “${name}” แล้ว`);
  }
  if(draft) draft.supplier=name;
  poRepresentativeEditorId=null;
  persistWorkspaceData();
  render();
}

function savePOSupplierFromPO(){
  if(currentTab==='goodsreceipt'&&loggedInUser()?.owner!==true){
    poSupplierEditorOpen=false;
    showToast('LEVEL 2 แก้ไขข้อมูลผู้จำหน่ายจากใบรับสินค้าไม่ได้');
    render();
    return;
  }
  syncPOFromDOM();
  const draft=activePurchaseDraft();
  const supplier=suppliersList().find(s=>s.name===draft.supplier); if(!supplier) return;
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const name=get('po_sup_name');
  if(!name){ showToast('กรุณากรอกชื่อผู้จำหน่าย'); document.getElementById('po_sup_name').focus(); return; }
  supplier.name=name;
  supplier.taxId=get('po_sup_taxid');
  supplier.contactName=get('po_sup_contact');
  supplier.phone=get('po_sup_phone');
  supplier.email=get('po_sup_email');
  supplier.creditDays=parseInt(get('po_sup_credit'))||0;
  supplier.address=get('po_sup_address');
  draft.supplier=name;
  poSupplierEditorOpen=false;
  persistWorkspaceData();
  showToast('บันทึกข้อมูลผู้จำหน่ายแล้ว');
  render();
}
function recalcPORow(row){
  const qty=parseFloat(row.querySelector('.poi_qty').value)||0;
  const priceEl=row.querySelector('.poi_price');
  const price=priceEl?(parseFloat(priceEl.value)||0):0;
  const totalEl=row.querySelector('.poi_total'); if(totalEl) totalEl.textContent=fmtMoney(qty*price);
  // อัปเดตยอดสรุปแบบเบาๆ โดยไม่ re-render ทั้งหน้า
  syncPOFromDOM();
  const draft=activePurchaseDraft();
  const tax=calculatePurchaseTaxSummary(draft.items,draft.discount||0,draft.taxMode||'incl');
  const amtEl=document.querySelector('.po-total-amt'); if(amtEl) amtEl.textContent=fmtMoney(tax.total);
}
function syncPOFromDOM(){
  const draft=activePurchaseDraft(); if(!draft) return;
  if((currentTab==='taxinvoice'&&editingTaxInvoiceSaleId==='manual-new')||(currentTab==='quotation'&&editingQuotationId!==null)){
    const date=document.getElementById('po_date'); if(date){ const iso=dmyToISO(date.value); if(iso) draft.date=iso; }
    const credit=document.getElementById('po_credit'); if(credit) draft.credit=parseInt(credit.value)||0;
    draft.dueDate=addDaysToDate(draft.date,draft.credit||0);
    const discount=document.getElementById('po_discount'); if(discount) draft.discount=parseFloat(discount.value)||0;
    const note=document.getElementById('po_note'); if(note) draft.note=note.value;
    const rows=document.querySelectorAll('#poItemRows .po-item-row');
    if(rows.length) draft.items=Array.from(rows).map(row=>{
      const name=row.querySelector('.poi_name').value;
      const matched=products.find(p=>p.name===name);
      return {name,qty:parseFloat(row.querySelector('.poi_qty').value)||0,unit:row.querySelector('.poi_unit').value.trim(),price:row.querySelector('.poi_price').value===''?'':(parseFloat(row.querySelector('.poi_price').value)||0),pid:matched?matched.id:null};
    });
    return;
  }
  const sup=document.getElementById('po_supplier'); if(sup) draft.supplier=sup.value;
  const warehouse=document.getElementById('po_warehouse'); if(warehouse) draft.warehouseId=Number(warehouse.value)||0;
  const d=document.getElementById('po_date'); if(d){ const iso=dmyToISO(d.value); if(iso) draft.date=iso; }
  const c=document.getElementById('po_credit'); if(c) draft.credit=parseInt(c.value)||0;
  if(currentTab==='goodsreceipt'||currentTab==='purchaseorder2') draft.dueDate=addDaysToDate(draft.date,draft.credit||0); else { draft.credit=0; draft.dueDate=''; draft.discount=0; }
  const disc=document.getElementById('po_discount'); if(disc) draft.discount=parseFloat(disc.value)||0;
  const taxMode=document.getElementById('po_tax_mode'); if(taxMode) draft.taxMode=taxMode.value;
  const taxNo=document.getElementById('po_supplier_tax_invoice_no'); if(taxNo) draft.supplierTaxInvoiceNo=taxNo.value.trim();
  const taxDate=document.getElementById('po_supplier_tax_invoice_date');
  if(taxDate){
    const raw=taxDate.value.trim();
    draft.supplierTaxInvoiceDate=raw?(dmyToISO(raw)||''):'';
  }
  const note=document.getElementById('po_note'); if(note) draft.note=note.value;
  const rows=document.querySelectorAll('#poItemRows .po-item-row');
  if(rows.length) draft.items=Array.from(rows).map((r,index)=>{
    const name=r.querySelector('.poi_name').value;
    const rowProduct=products.find(product=>Number(product.id)===Number(r.dataset.productId));
    const matched=rowProduct?.name===name?rowProduct:documentProductPool().find(product=>product.name===name);
    return {
      productId:matched?.id||'',name,
      qty:parseFloat(r.querySelector('.poi_qty').value)||0,
      unit:r.querySelector('.poi_unit').value.trim(),
      price:r.querySelector('.poi_price')?(r.querySelector('.poi_price').value===''?'':(parseFloat(r.querySelector('.poi_price').value)||0)):0,
      ...(currentTab==='goodsreceipt'?{
        lineId:String(draft.items?.[index]?.lineId||index+1),
        warehouseId:Number(draft.warehouseId)||0,
        lotNumber:r.querySelector('.poi_lot')?.value.trim()||'',
        expiry:(()=>{ const raw=r.querySelector('.poi_expiry')?.value.trim()||''; return raw?(dmyToISO(raw)||raw):''; })()
      }:currentTab==='productreturn'?(()=>{
        const lotSelect=r.querySelector('.poi_return_lot');
        const selected=lotSelect?.selectedOptions?.[0];
        return {
          lineId:String(draft.items?.[index]?.lineId||index+1),
          warehouseId:Number(draft.warehouseId)||0,
          lotId:Number(lotSelect?.value)||null,
          lotNumber:selected?.dataset?.lotNumber||'',
          expiry:selected?.dataset?.expiry||''
        };
      })():{}),
    };
  });
}
async function savePO(silent=false){
  silent = silent===true;
  syncPOFromDOM();
  const kind=currentDocKind();
  const styled=isSupplierStyleDoc(kind);
  const draft=activePurchaseDraft();
  const editingId=docEditingId(kind);
  const list=docList(kind);
  if(!draft.supplier){ showToast(styled?'กรุณาเลือกผู้จำหน่าย':'กรุณาเลือกผู้แทน'); return false; }
  if((kind==='gr'||kind==='ret')&&!Number(draft.warehouseId)){ showToast(kind==='gr'?'กรุณาเลือกคลัง / สาขาที่รับสินค้าเข้า':'กรุณาเลือกคลัง / สาขาที่คืนสินค้าออก'); return false; }
  const items=draft.items.filter(it=>it.name && it.qty>0);
  if(items.length===0){ showToast('กรุณาเพิ่มรายการสินค้าอย่างน้อย 1 รายการ'); return false; }
  if(items.some(it=>!products.some(p=>p.name===it.name))){ showToast('กรุณาเลือกสินค้าจากผลการค้นหา'); return false; }
  if(kind==='gr'&&items.some(item=>item.expiry&&!/^\d{4}-\d{2}-\d{2}$/.test(item.expiry))){ showToast('กรุณากรอกวันหมดอายุเป็น วัน-เดือน-ปี เช่น 05-07-2027'); return false; }
  if(kind==='ret'&&items.some(item=>!Number(item.lotId))){ showToast('กรุณาเลือก Lot ที่คืนให้ครบทุกสินค้า'); return false; }
  const tax=styled?calculatePurchaseTaxSummary(items,draft.discount||0,draft.taxMode||'incl'):calculatePurchaseTaxSummary([],0,'none');
  const old=editingId!=='new'?list.find(x=>x.id===editingId):null;
  const savedItems=(kind==='gr'||kind==='ret')?normalizeGoodsReceiptItems(items,draft.warehouseId):items;
  if(kind==='gr'&&old?.stockApplied===true){ showToast('ใบรับสินค้านี้รับเข้าสต๊อกแล้ว จึงแก้ไขเอกสารไม่ได้ กรุณาพิมพ์หรือดูจากรายการเดิม','danger-top'); return false; }
  if(kind==='ret'&&old?.stockApplied===true){
    const stockShape=value=>(value||[]).map(item=>({productId:Number(item.productId)||0,qty:Number(item.qty)||0,unit:item.unit||'',stockFactor:Number(item.stockFactor)||1,lotId:Number(item.lotId)||0}));
    if(Number(old.warehouseId)!==Number(draft.warehouseId)||JSON.stringify(stockShape(old.items))!==JSON.stringify(stockShape(savedItems))){
      showToast('ใบคืนสินค้านี้ตัดสต๊อกแล้ว จึงแก้สินค้า จำนวน หน่วย หรือ Lot ไม่ได้');
      return false;
    }
  }
  const rec={ id:draft.id, _revision:Number(old?._revision)||0, supplier:draft.supplier, date:draft.date, credit:kind==='ret'?0:(styled?(draft.credit||0):0), dueDate:kind==='ret'?'':(styled?addDaysToDate(draft.date,draft.credit||0):''), items:savedItems, discount:kind==='ret'?0:(styled?(draft.discount||0):0), total:kind==='ret'?0:tax.total, taxMode:kind==='ret'?'none':(styled?(draft.taxMode||'incl'):'none'), taxSummary:kind==='ret'?calculatePurchaseTaxSummary([],0,'none'):(styled?tax:null), supplierTaxInvoiceNo:styled?(draft.supplierTaxInvoiceNo||''):'', supplierTaxInvoiceDate:styled?(draft.supplierTaxInvoiceDate||''):'', businessSnapshot:old?.businessSnapshot||businessDocumentSnapshot(), note:draft.note||'', status:old?.status||docDefaultStatus(kind), ...(kind==='gr'?{warehouseId:Number(draft.warehouseId),stockApplied:old?.stockApplied===true,stockAppliedAt:old?.stockAppliedAt||'',createdByUserId:old?.createdByUserId||String(currentProfile?.id||'')}:kind==='ret'?{warehouseId:Number(draft.warehouseId),stockApplied:old?.stockApplied===true,stockAppliedAt:old?.stockAppliedAt||''}:{}) };
  if(kind==='gr'){
    const saveButton=document.getElementById('savePOBtn');
    if(saveButton) saveButton.disabled=true;
    try{
      if(old&&!canManageGoodsReceipt(old)) throw new Error('แก้ไขไม่ได้ เพราะใบรับสินค้านี้สร้างโดยผู้ใช้งานอื่น');
      await saveRevisionedDocument('goods_receipts',rec);
    }catch(error){
      console.warn('save goods receipt',error);
      if(saveButton) saveButton.disabled=false;
      const message=error?.code==='23505'?'เลขที่ใบรับสินค้านี้ถูกใช้งานแล้ว กรุณาปิดหน้าต่างและสร้างเอกสารใหม่':(error?.message||'กรุณาตรวจการเชื่อมต่อแล้วลองใหม่');
      showToast(`บันทึกใบรับสินค้าไม่สำเร็จ: ${message}`,'danger-top');
      return false;
    }
  }
  if(editingId==='new'){
    list.unshift(rec);
    if(kind==='gr'){ grCounter++; }
    else if(kind==='ret'){ returnCounter++; }
    else bumpDocCounter(kind);
  } else {
    const idx=list.findIndex(x=>x.id===editingId);
    if(idx>-1){
      list[idx]=rec;
    }
  }
  if(kind==='gr') seedTableSnapshot('goods_receipts',goodsReceipts,docToRow);
  const savedId=rec.id;
  persistWorkspaceData();
  if(!silent){ setDocEditingId(kind,null); setDocDraft(kind,null); if(kind==='po') poRepresentativeEditorId=null; showToast(`บันทึก${docLabelText(kind)}แล้ว`); render(); }
  else { setDocEditingId(kind,savedId); }
  return savedId;
}

async function handleDocumentAction(kind,id,action){
  const list=docList(kind);
  const doc=list.find(x=>x.id===id); if(!doc) return;
  openDocMenu=null;
  if(action==='edit'){
    if(kind==='gr'&&!canManageGoodsReceipt(doc)){ showToast('แก้ไขไม่ได้ เพราะใบรับสินค้านี้สร้างโดยผู้ใช้งานอื่น','danger-top'); render(); return; }
    if(kind==='gr'&&documentHasPostedStock(kind,doc)){ showToast('ใบรับสินค้านี้รับเข้าสต๊อกแล้ว จึงแก้ไขเอกสารไม่ได้','danger-top'); render(); return; }
    setDocEditingId(kind,id); setDocDraft(kind,null);
    if(kind==='po') poRepresentativeEditorId=null;
    currentTab = kind==='gr'?'goodsreceipt':kind==='po2'?'purchaseorder2':kind==='ret'?'productreturn':'purchaseorder';
    render(); return;
  }
  if(action==='print'){ printPO(id,kind); render(); return; }
  if(action==='duplicate'&&kind!=='gr'){
    const copy=JSON.parse(JSON.stringify(doc));
    copy.id=docPrefix(kind)+TODAY_STR.replace(/-/g,'')+String(docCounter(kind)).padStart(4,'0'); copy.date=TODAY_STR; copy.dueDate=addDaysToDate(copy.date,copy.credit||0); copy.status=docDefaultStatus(kind);
    if(kind==='ret'){
      copy.items=normalizeGoodsReceiptItems(copy.items,copy.warehouseId).map((item,index)=>({...item,lineId:String(index+1),lotId:null,lotNumber:'',expiry:''}));
      copy.status='รอรับคืน';
      copy.stockApplied=false;
      copy.stockAppliedAt='';
      copy.lotAppliedAt='';
    }
    bumpDocCounter(kind);
    list.unshift(copy);
    persistWorkspaceData(); showToast(`สร้างซ้ำเป็น ${copy.id} แล้ว`); render(); return;
  }
  if(action==='delete'){
    if(kind==='gr'&&!canManageGoodsReceipt(doc)){ showToast('ลบไม่ได้ เพราะใบรับสินค้านี้สร้างโดยผู้ใช้งานอื่น','danger-top'); render(); return; }
    if(refusePostedDocumentDeletion(kind,doc)){ render(); return; }
    if(confirm(`ยืนยันลบ ${doc.id} ?`)){
      if(kind==='gr'){
        try{
          const {data,error}=await sb.from('goods_receipts').delete().eq('id',doc.id).select('id');
          if(error) throw error;
          if(!(data||[]).length){ showToast('ลบใบรับสินค้าไม่สำเร็จ ระบบไม่อนุญาตให้ลบรายการนี้','danger-top'); render(); return; }
        }catch(error){
          console.warn('delete goods receipt',error);
          showToast(`ลบใบรับสินค้าไม่สำเร็จ: ${error?.message||'กรุณาลองใหม่'}`,'danger-top');
          render();
          return;
        }
      }
      const idx=list.findIndex(x=>x.id===id); if(idx>-1) list.splice(idx,1);
      if(kind==='gr') seedTableSnapshot('goods_receipts',goodsReceipts,docToRow);
      persistWorkspaceData();
      showToast(`ลบ ${doc.id} แล้ว`);
    }
    render();
  }
}

function setupA4DocumentPreview(win,{number,label,pageSelector}){
  const doc=win.document;
  const originalPages=[...doc.querySelectorAll(pageSelector)].map(page=>page.cloneNode(true));
  if(!originalPages.length) return;
  const style=doc.createElement('style');
  style.textContent=`
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
    body{padding-top:66px!important;padding-right:285px!important;background:#F0F0F0!important}
    .toolbar{position:fixed!important;top:0!important;left:0!important;right:0!important;z-index:30!important;height:66px!important;margin:0!important;padding:10px 18px!important;background:#fff!important;border-bottom:1px solid #dce3e8!important;box-shadow:none!important;display:flex!important;align-items:center!important;gap:14px!important}
    .preview-actions{display:flex;align-items:center;gap:10px;margin-left:auto}
    .preview-actions button{height:42px;min-width:142px;border-radius:6px;font:600 15px Sarabun;cursor:pointer}
    .preview-actions .close-preview{background:#fff!important;color:#6d7882!important;border:1px solid #bfc9d2!important}
    .preview-actions .confirm-preview-print{background:#4F4038!important;color:#fff!important;border:1px solid #4F4038!important}
    .document-print-sidebar{position:fixed;top:66px;right:0;bottom:0;z-index:25;width:285px;padding:20px 22px;background:#fff;border-left:1px solid #dce3e8;color:#1f2933}
    .document-print-sidebar h3{margin:0 0 14px;font-size:17px}
    .document-print-options{display:flex;align-items:center;gap:18px}
    .document-print-options label{display:flex;align-items:center;gap:7px;font-weight:600;white-space:nowrap}
    .document-print-options input[type=checkbox]{width:18px;height:18px;accent-color:#4F4038}
    .document-print-options input[type=number]{width:62px;height:38px;padding:6px 8px;border:1px solid #ccd5dd;border-radius:7px;font:600 14px Sarabun}
    ${pageSelector}{width:210mm!important;min-height:297mm!important;height:auto!important;margin:12px auto!important;padding:16mm 18mm!important;background:#fff!important;box-shadow:0 4px 20px #0002!important;page-break-after:always!important}
    ${pageSelector}:last-child{page-break-after:auto!important}
    .business{padding-top:50px!important}.business b{color:#4F4038!important;font-weight:700!important}
    .title-block{text-align:center!important}.title{margin-bottom:2px!important}.subtitle{color:#4F4038;font-size:12px;margin-bottom:8px}
    .docmeta{display:grid!important;width:100%!important;text-align:left!important;border-top:2px solid #d5d5d5;border-bottom:2px solid #d5d5d5;padding:12px 8px!important;margin-top:8px!important}
    .customer>div:nth-child(2){color:#4F4038;font-weight:700}.items th{background:#4F4038!important;color:#fff!important}
    .totals .lbl{color:#151515!important}.totals .grand span{color:#4F4038!important}.words{display:none!important}
    @media print{body{padding:0!important;background:#fff!important}.toolbar,.document-print-sidebar{display:none!important}${pageSelector}{margin:0 auto!important;box-shadow:none!important}}
  `;
  doc.head.appendChild(style);
  const setPageLabel=(page,text)=>{
    const titleBlock=page.querySelector('.title-block'); if(!titleBlock) return;
    let subtitle=titleBlock.querySelector('.subtitle');
    if(!subtitle){ subtitle=doc.createElement('div'); subtitle.className='subtitle'; const title=titleBlock.querySelector('.title'); title?.insertAdjacentElement('afterend',subtitle); }
    subtitle.textContent=text;
  };
  doc.querySelectorAll(pageSelector).forEach(page=>setPageLabel(page,'ต้นฉบับ'));
  const toolbar=doc.querySelector('.toolbar,.screenbar');
  if(toolbar){
    toolbar.className='toolbar';
    toolbar.innerHTML=`<div class="preview-actions"><button type="button" class="close-preview" id="closeDocumentPreview">ย้อนกลับ</button><button type="button" class="confirm-preview-print" id="confirmDocumentPrint">พิมพ์</button></div>`;
  }
  const sidebar=doc.createElement('aside');
  sidebar.className='document-print-sidebar';
  sidebar.innerHTML=`<h3>${escapeHtml(label)}</h3><div class="document-print-options"><label><input id="documentOriginalOption" type="checkbox" checked> ต้นฉบับ</label><label><input id="documentCopyOption" type="checkbox" checked> สำเนา</label><input id="documentCopyCount" type="number" min="1" max="20" value="1" aria-label="จำนวนสำเนา"></div>`;
  doc.body.appendChild(sidebar);
  const rebuildPages=()=>{
    const includeOriginal=doc.getElementById('documentOriginalOption').checked;
    const includeCopy=doc.getElementById('documentCopyOption').checked;
    const copyCount=Math.max(1,Math.min(20,Number(doc.getElementById('documentCopyCount').value)||1));
    if(!includeOriginal&&!includeCopy){ win.alert('กรุณาเลือกต้นฉบับหรือสำเนาอย่างน้อย 1 รายการ'); return false; }
    doc.querySelectorAll(pageSelector).forEach(page=>page.remove());
    const appendPages=text=>originalPages.forEach(template=>{ const page=template.cloneNode(true); setPageLabel(page,text); doc.body.appendChild(page); });
    if(includeOriginal) appendPages('ต้นฉบับ');
    if(includeCopy) for(let i=0;i<copyCount;i++) appendPages('สำเนา');
    return true;
  };
  doc.getElementById('closeDocumentPreview').onclick=()=>win.close();
  doc.getElementById('confirmDocumentPrint').onclick=()=>{ if(rebuildPages()) win.print(); };
}

function printPO(poId,kind='po'){
  const styled=isSupplierStyleDoc(kind);
  const titleText=docLabelText(kind);
  const ids=Array.isArray(poId)?poId:[poId];
  const list=docList(kind);
  const docs=ids.map(id=>list.find(x=>x.id===id)).filter(Boolean); if(!docs.length) return;
  const pages=docs.map(po=>{
    const tax=po.taxSummary||calculatePurchaseTaxSummary(po.items,po.discount||0,po.taxMode||'incl');
    const business=po.businessSnapshot||businessSettings;
    const supplier=styled?suppliersList().find(s=>s.name===po.supplier):salesRepresentatives.find(rep=>rep.name===po.supplier);
    const rows=po.items.map((it,i)=>styled?`<tr><td class="c">${i+1}</td><td>${escapeHtml(it.name)}</td><td class="r">${escapeHtml(it.qty)}</td><td>${escapeHtml(it.unit||'')}</td><td class="r">${fmtMoney(it.price)}</td><td class="r">${fmtMoney(it.qty*it.price)}</td></tr>`:`<tr><td class="c">${i+1}</td><td>${escapeHtml(it.name)}</td><td class="r">${escapeHtml(it.qty)}</td><td>${escapeHtml(it.unit||'')}</td></tr>`).join('');
    return `<section class="a4-page">
      <section class="header">
        <div class="business"><b style="font-size:13px;">${escapeHtml(businessDocumentName(business,STORE_INFO.name))}</b><br>${escapeHtml(business.address||STORE_INFO.address)}${(business.taxId||STORE_INFO.taxId)?`<br>เลขประจำตัวผู้เสียภาษี ${escapeHtml(business.taxId||STORE_INFO.taxId)}`:''}${businessPrimaryPhone(business)?`<br>เบอร์ติดต่อ ${escapeHtml(businessPrimaryPhone(business))}`:''}${(business.website||STORE_INFO.website)?`<br>${escapeHtml(business.website||STORE_INFO.website)}`:''}</div>
        <div class="title-block"><div class="title">${escapeHtml(titleText)}</div><div class="docmeta"><span>เลขที่</span><span>${escapeHtml(po.id)}</span><span>${styled?'วันที่':'วันที่สั่ง'}</span><span>${escapeHtml(fmtDateShort(po.date))}</span>${styled?`<span>ครบกำหนด</span><span>${escapeHtml(fmtDateShort(documentDueDate(po)))}</span>`:''}<span>ผู้สั่งซื้อ</span><span>${escapeHtml(loggedInUser()?.firstName||employees[0])}</span></div></div>
      </section>
      <section class="customer"><div class="lbl">${styled?'ผู้จำหน่าย':'ผู้แทน'}</div><div><b>${escapeHtml(po.supplier)}</b></div><div>${styled?`${escapeHtml(supplier?.address||'-')}${supplier?.taxId?`<br>เลขประจำตัวผู้เสียภาษี ${escapeHtml(supplier.taxId)}`:''}`:`เบอร์โทร ${escapeHtml(supplier?.phone||'-')}<br>ไลน์ ${escapeHtml(supplier?.line||'-')}${supplier?.note?`<br>${escapeHtml(supplier.note)}`:''}`}</div></section>
      <table class="items"><thead><tr><th class="c">#</th><th>รายละเอียด</th><th class="r">จำนวน</th><th>หน่วย</th>${styled?'<th class="r">ราคาต่อหน่วย</th><th class="r">ยอดรวม</th>':''}</tr></thead><tbody>${rows}</tbody></table>
      ${styled?`<section class="totals"><div><span class="lbl">รวมเป็นเงิน</span><b>${fmtMoney(tax.subtotal)} บาท</b></div>${po.discount?`<div><span class="lbl">ส่วนลด</span><b>${fmtMoney(po.discount)} บาท</b></div>`:''}${tax.registered?`<div><span class="lbl">ภาษีมูลค่าเพิ่ม 7%</span><b>${fmtMoney(tax.vat)} บาท</b></div><div class="last-sub"><span class="lbl">มูลค่าก่อนภาษีมูลค่าเพิ่ม</span><b>${fmtMoney(tax.beforeVat)} บาท</b></div>`:`<div class="last-sub"><span class="lbl">ไม่มี VAT</span><b>0.00 บาท</b></div>`}<div class="grand"><span>จำนวนเงินรวมทั้งสิ้น</span><b>${fmtMoney(tax.total)} บาท</b></div></section><div class="words">(${bahtText(tax.total)})</div>`:`<div style="margin-top:8mm;font-size:12px;"><b>หมายเหตุ:</b> ${escapeHtml(po.note||'-')}</div>`}
      <div class="signheads"><span>ในนาม ${escapeHtml(po.supplier)}</span><span>ในนาม ${escapeHtml(business.name||STORE_INFO.name)}</span></div>
      <div class="signlines"><div>${styled?'ผู้ขาย':'ผู้แทน'} · วันที่</div><div>${styled?'ผู้รับสินค้า':'ผู้อนุมัติ'} · วันที่</div></div>
    </section>`;
  }).join('');
  const win=window.open('','_blank');
  win.document.write(`<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><title>${docs.map(d=>escapeHtml(d.id)).join(', ')}</title><link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;500;600;700&display=swap" rel="stylesheet"><style>
    @page{size:A4 portrait;margin:0;}*{box-sizing:border-box;}html,body{margin:0;padding:0;}body{font-family:'Sarabun',sans-serif;background:#F0F0F0;color:#151515;font-size:10.5pt;}
    .screenbar{position:sticky;top:0;z-index:99;display:flex;justify-content:space-between;align-items:center;padding:10px 18px;background:#fff;box-shadow:0 2px 8px #0002}.screenbar button{border:0;border-radius:7px;background:#4F4038;color:#fff;padding:9px 18px;font:600 14px Sarabun;cursor:pointer}
    .a4-page{width:210mm;height:297mm;margin:10mm auto;background:#fff;position:relative;padding:16mm 18mm;overflow:hidden;page-break-after:always;box-shadow:0 4px 20px #0002}.a4-page:last-child{page-break-after:auto}
    .header{display:grid;grid-template-columns:1.15fr 1fr;gap:14mm;margin-top:2mm}.business{font-size:11.5px;line-height:1.6}.title-block{text-align:right}.title{color:#4F4038;font-size:22px;font-weight:700;margin-bottom:8px}.docmeta{display:inline-grid;grid-template-columns:auto auto;gap:4px 14px;text-align:left;font-size:12px}.docmeta span:nth-child(odd){color:#4F4038;font-weight:600}
    .customer{margin:9mm 0 5mm}.customer .lbl{color:#4F4038;font-weight:600;font-size:12px;margin-bottom:2px}.customer div{font-size:12px;line-height:1.5}
    table.items{width:100%;border-collapse:collapse;font-size:12px;margin-top:2mm}table.items th{background:#4F4038;color:#fff;padding:7px 8px;text-align:left;font-weight:600}table.items th.r,table.items td.r{text-align:right}table.items th.c,table.items td.c{text-align:center;width:9mm}table.items td{padding:7px 8px;border-bottom:1px solid #e4e8ec}
    .totals{width:82mm;margin:6mm 0 0 auto;font-size:12.5px}.totals div{display:flex;justify-content:space-between;padding:4px 0}.totals .lbl{color:#4F4038}.totals .last-sub{border-bottom:1px solid #4F4038;padding-bottom:6px}.totals .grand{font-weight:700;margin-top:2px;padding-top:6px}
    .words{font-size:12px;margin-top:8mm;text-align:right}
    .signheads{position:absolute;left:18mm;right:18mm;bottom:30mm;display:flex;justify-content:space-between;font-size:12px}.signheads span{width:60mm;text-align:center}
    .signlines{position:absolute;left:18mm;right:18mm;bottom:14mm;display:flex;justify-content:space-between;text-align:center;font-size:11px}.signlines div{width:60mm;border-top:1px solid #888;padding-top:4px}
    @media print{body{background:#fff}.screenbar{display:none}.a4-page{margin:0;box-shadow:none}}
  </style></head><body><div class="screenbar"><span>ตัวอย่างเอกสาร A4</span><button onclick="window.print()">พิมพ์เอกสาร</button></div>${pages}</body></html>`);
  win.document.close();
  standardizePrintPreview(win);
  if(kind==='po2'||kind==='gr') setupA4DocumentPreview(win,{number:docs.map(doc=>doc.id).join(', '),label:titleText,pageSelector:'.a4-page'});
}
// แปลงตัวเลขเป็นข้อความภาษาไทย (บาท/สตางค์)
function bahtText(num){
  num=Math.round(num*100)/100;
  const txt=['ศูนย์','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'];
  const pos=['','สิบ','ร้อย','พัน','หมื่น','แสน','ล้าน'];
  function conv(n){
    n=String(parseInt(n)); let s='';
    for(let i=0;i<n.length;i++){
      const d=+n[i], p=n.length-i-1;
      if(d===0) continue;
      if(p===1 && d===1) s+='สิบ';
      else if(p===1 && d===2) s+='ยี่สิบ';
      else if(p===0 && d===1 && n.length>1) s+='เอ็ด';
      else s+=txt[d]+pos[p%6];
      if(p===6) s+='ล้าน';
    }
    return s||'ศูนย์';
  }
  const baht=Math.floor(num); const satang=Math.round((num-baht)*100);
  let r=conv(baht)+'บาท';
  r+= satang===0 ? 'ถ้วน' : conv(satang)+'สตางค์';
  return r;
}

async function saveBusinessSettings(){
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const vat=get('set_business_vat'),taxId=get('set_business_tax').replace(/\D/g,''),selectedBranch=document.querySelector('input[name="set_branch"]:checked')?.value||'none',branch=vat===VAT_REGISTERED_LABEL?selectedBranch:'none';
  const vatDateText=get('set_business_vat_date'),vatRegistrationDate=vatDateText?dmyToISO(vatDateText):'';
  if(taxId&&!/^\d{13}$/.test(taxId)){ showToast('เลขประจำตัวผู้เสียภาษีต้องมี 13 หลัก','danger'); document.getElementById('set_business_tax')?.focus(); return; }
  if(vat===VAT_REGISTERED_LABEL){
    if(!get('set_business_name')||!get('set_business_address')){ showToast('กรุณากรอกชื่อและที่อยู่ธุรกิจให้ครบก่อนเปิดใช้ VAT','danger'); return; }
    if(!taxId){ showToast('กรุณากรอกเลขประจำตัวผู้เสียภาษี 13 หลัก','danger'); document.getElementById('set_business_tax')?.focus(); return; }
    if(!vatRegistrationDate){ showToast('กรุณากรอกวันที่เริ่มจด VAT ตาม ภ.พ.20 เป็น วัน-เดือน-ปี','danger'); document.getElementById('set_business_vat_date')?.focus(); return; }
    if(!['head','branch'].includes(branch)){ showToast('กรุณาเลือกสำนักงานใหญ่หรือสาขาตาม ภ.พ.20','danger'); return; }
    if(branch==='branch'&&!/^\d{5}$/.test(get('set_business_branch_code'))){ showToast('รหัสสาขาต้องมี 5 หลัก','danger'); document.getElementById('set_business_branch_code')?.focus(); return; }
    if(branch==='branch'&&!get('set_business_branch_name')){ showToast('กรุณากรอกชื่อสาขา','danger'); document.getElementById('set_business_branch_name')?.focus(); return; }
  }
  applyBusinessSettings({type:get('set_business_type'),vat,vatRegistrationDate,name:get('set_business_name'),address:get('set_business_address'),taxId,branch,branchCode:get('set_business_branch_code'),branchName:get('set_business_branch_name'),officePhone:get('set_business_office'),mobile:get('set_business_mobile'),fax:get('set_business_fax'),line:get('set_business_line'),website:get('set_business_website'),documentPhone:get('set_business_document_phone')==='office'?'office':'mobile',english:businessSettings.english||false});
  persistWorkspaceData(); // localStorage now, Supabase after the usual debounce
  businessSettingsDirty=false;
  businessSettingsSyncState='syncing';
  render();
  const synced=await syncBusinessSettingsToSupabase();
  showToast(synced?'บันทึกและซิงก์ข้อมูลธุรกิจแล้ว':'บันทึกในเครื่องแล้ว แต่ซิงก์ Supabase ไม่สำเร็จ',synced?'':'danger');
  render();
}

function saveDocumentPrefixes(){
  const next={};
  const used=new Map();
  for(const field of DOCUMENT_PREFIX_FIELDS){
    const input=document.getElementById(`doc_prefix_${field.key}`);
    const value=normalizeDocumentPrefix(input?.value,'');
    if(!value){
      showToast(`กรุณากรอกรหัสนำหน้า ${field.label}`);
      input?.focus();
      return;
    }
    if(used.has(value)){
      showToast(`รหัส ${value} ซ้ำกับ ${used.get(value)} กรุณาใช้รหัสที่ไม่ซ้ำกัน`);
      input?.focus();
      return;
    }
    used.set(value,field.label);
    next[field.key]=value;
  }
  documentPrefixes={...next};
  saleRef=nextSaleRef();
  persistWorkspaceData();
  syncDocumentPrefixesToSupabase();
  showToast('บันทึกรหัสนำหน้าเอกสารแล้ว เอกสารใหม่จะใช้รหัสที่ตั้งไว้');
  render();
}

async function storeBackupDataSnapshot(){
  const data=cloudClean(workspaceSnapshot());
  delete data.cart;
  delete data.saleDiscount;
  delete data.saleMember;
  delete data.pendingQty;
  const {data:inventoryBackup,error}=await sb.rpc('export_store_inventory_backup');
  if(error) throw error;
  if(!inventoryBackup||!Array.isArray(inventoryBackup.lots)||!Array.isArray(inventoryBackup.movements)) throw new Error('ไม่สามารถอ่านประวัติ LOT และการเคลื่อนไหวสต๊อกได้ครบถ้วน');
  data.inventoryBackup=inventoryBackup;
  return data;
}

function storeBackupFileName(){
  const now=new Date(),pad=value=>String(value).padStart(2,'0');
  return `PEPOS-backup-${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}.json`;
}

async function downloadStoreBackup(){
  if(loggedInUser()?.owner!==true){ showToast('เฉพาะเจ้าของร้านเท่านั้นที่สามารถสำรองข้อมูลได้'); return; }
  const button=document.getElementById('downloadStoreBackupBtn');
  const oldLabel=button?.textContent||'ดาวน์โหลดไฟล์สำรอง';
  if(button){ button.disabled=true; button.textContent='กำลังเตรียมไฟล์...'; }
  try{
    const createdAt=new Date().toISOString();
    const data=await storeBackupDataSnapshot();
    const payload={
      format:STORE_BACKUP_FORMAT,
      version:STORE_BACKUP_VERSION,
      createdAt,
      businessName:businessSettings.name||STORE_INFO.name||'',
      summary:storeBackupSummary(data),
      data
    };
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'});
    const url=URL.createObjectURL(blob);
    const link=document.createElement('a');
    link.href=url;
    link.download=storeBackupFileName();
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
    localStorage.setItem(STORE_BACKUP_LAST_KEY,createdAt);
    showToast('ดาวน์โหลดไฟล์สำรองข้อมูลร้านแล้ว');
    render();
  }catch(error){
    console.error('สำรองข้อมูลร้านไม่สำเร็จ',error);
    showToast('สร้างไฟล์สำรองไม่สำเร็จ กรุณาลองอีกครั้ง','danger');
    if(button){ button.disabled=false; button.textContent=oldLabel; }
  }
}

async function submitStoreReset(event){
  event?.preventDefault();
  if(loggedInUser()?.owner!==true||!storeResetMode){ showToast('เฉพาะเจ้าของร้านเท่านั้นที่สามารถรีเซ็ตข้อมูลได้','danger'); return; }
  const mode=storeResetMode,config=storeResetConfig(mode);
  const password=document.getElementById('storeResetPassword')?.value||'';
  const phrase=(document.getElementById('storeResetPhrase')?.value||'').trim();
  const backupConfirmed=document.getElementById('storeResetBackupConfirmed')?.checked===true;
  if(!password){ showToast('กรุณากรอกรหัสผ่านเจ้าของร้าน','danger'); document.getElementById('storeResetPassword')?.focus(); return; }
  if(phrase!==config.phrase){ showToast(`กรุณาพิมพ์ “${config.phrase}” ให้ถูกต้อง`,'danger'); document.getElementById('storeResetPhrase')?.focus(); return; }
  if(!backupConfirmed){ showToast('กรุณายืนยันว่าได้ดาวน์โหลดไฟล์สำรองแล้ว','danger'); return; }
  const button=document.getElementById('confirmStoreResetBtn');
  if(button){ button.disabled=true; button.textContent='กำลังรีเซ็ตข้อมูล...'; }
  try{
    const response=await callEdgeFunction('admin-users',{action:'reset-store',mode,password,phrase});
    const bootstrapToken=String(response?.reset?.bootstrapToken||'');
    if(mode==='factory'&&!bootstrapToken) throw new Error('ระบบไม่ได้รับกุญแจตั้งค่าเจ้าของร้าน กรุณาติดต่อผู้ดูแลระบบก่อนปิดหน้านี้');
    await clearLocalStoreCachesForReset();
    if(bootstrapToken) localStorage.setItem(OWNER_BOOTSTRAP_TOKEN_STORAGE_KEY,bootstrapToken);
    storeResetMode=null;
    if(mode==='factory'){
      try{ await sb.auth.signOut({scope:'local'}); }catch(error){}
      alert('คืนค่าโรงงานเรียบร้อยแล้ว โปรแกรมจะเปิดหน้าสร้าง ID เจ้าของร้านคนแรก');
    }else{
      alert('ล้างเอกสาร LOT และสต๊อกเรียบร้อยแล้ว รายการสินค้ายังคงอยู่และยอดคงเหลือเป็นศูนย์');
    }
    window.location.reload();
  }catch(error){
    console.error('รีเซ็ตข้อมูลร้านไม่สำเร็จ',error);
    showToast(error.message||'รีเซ็ตข้อมูลไม่สำเร็จ กรุณาลองใหม่','danger');
    if(button){ button.disabled=false; button.textContent=config.button; }
  }
}

function validateStoreBackupPayload(payload){
  if(!payload||typeof payload!=='object'||payload.format!==STORE_BACKUP_FORMAT) throw new Error('ไฟล์นี้ไม่ใช่ไฟล์สำรองของ PEPOS');
  if(Number(payload.version)!==STORE_BACKUP_VERSION) throw new Error('ไฟล์สำรองเป็นเวอร์ชันที่ระบบนี้ยังไม่รองรับ');
  const data=payload.data;
  if(!data||typeof data!=='object') throw new Error('ไม่พบข้อมูลร้านในไฟล์สำรอง');
  const requiredArrays=['warehouses','products','contacts','salesRepresentatives','salesHistory','quotations','invoicesAR','creditNotes','purchaseOrders','goodsReceipts','purchaseOrdersFull','productReturns','transfers','standaloneTaxInvoices','favorites'];
  if(requiredArrays.some(key=>!Array.isArray(data[key]))) throw new Error('ข้อมูลในไฟล์สำรองไม่ครบถ้วน');
  if(!Array.isArray(data.productExchanges)) data.productExchanges=[];
  if(data.promotions!==undefined&&!Array.isArray(data.promotions)) throw new Error('ข้อมูลโปรโมชั่นในไฟล์สำรองไม่ถูกต้อง');
  if(!data.inventoryBackup||!Array.isArray(data.inventoryBackup.lots)||!Array.isArray(data.inventoryBackup.movements)) throw new Error('ไฟล์สำรองนี้ไม่มีประวัติ LOT และการเคลื่อนไหวสต๊อก กรุณาใช้ไฟล์สำรองเวอร์ชันใหม่');
  return cloudClean(data);
}

async function restoreStoreBackup(file){
  if(loggedInUser()?.owner!==true){ showToast('เฉพาะเจ้าของร้านเท่านั้นที่สามารถกู้คืนข้อมูลได้'); return; }
  if(!file||file.size>100*1024*1024){ showToast('ไฟล์สำรองมีขนาดใหญ่เกินไป','danger'); return; }
  let payload,data;
  try{
    payload=JSON.parse(await file.text());
    data=validateStoreBackupPayload(payload);
  }catch(error){
    console.error('ตรวจไฟล์สำรองไม่สำเร็จ',error);
    showToast(error.message||'อ่านไฟล์สำรองไม่สำเร็จ','danger');
    return;
  }
  const summary=storeBackupSummary(data);
  const backupDate=new Date(payload.createdAt||'');
  const dateText=!Number.isNaN(backupDate.getTime())?backupDate.toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short'}):'ไม่ระบุเวลา';
  const warning=`ยืนยันกู้คืนข้อมูลร้านจากไฟล์สำรองหรือไม่?\n\nวันที่สำรอง: ${dateText}\nสินค้า: ${summary.products} รายการ\nLOT: ${summary.lots} รายการ\nการเคลื่อนไหวสต๊อก: ${summary.movements} รายการ\nรายชื่อ: ${summary.contacts} รายการ\nโปรโมชั่น: ${summary.promotions} รายการ\nเอกสารและรายการขาย: ${summary.documents} รายการ\n\nข้อมูลปัจจุบันในร้านจะถูกแทนที่ด้วยข้อมูลจากไฟล์นี้`;
  if(!confirm(warning)) return;
  try{ localStorage.setItem(RESET_BACKUP_KEY,JSON.stringify(workspaceSnapshot())); }catch(error){ console.warn('ไม่สามารถเก็บข้อมูลก่อนกู้คืนไว้ในอุปกรณ์ได้',error); }
  const button=document.getElementById('restoreStoreBackupBtn');
  if(button){ button.disabled=true; button.textContent='กำลังกู้คืนข้อมูล...'; }
  try{
    const {data:result,error}=await sb.rpc('restore_store_backup_atomic',{p_backup:payload});
    if(error) throw error;
    await clearLocalStoreCachesForReset();
    clearRemoteResetSensitiveMemory();
    maintenanceEpoch=String(result?.epoch||'');
    if(maintenanceEpoch) localStorage.setItem(MAINTENANCE_EPOCH_STORAGE_KEY,maintenanceEpoch);
    await Promise.all([
      loadCoreDataFromSupabase(),loadSalesHistoryFromSupabase(),loadBusinessSettingsFromSupabase(),
      loadDocumentPrefixesFromSupabase(),loadInspectionListsFromSupabase(),loadPromotionsFromSupabase(),loadFavoritesFromSupabase()
    ]);
    await loadCashShiftsFromSupabase();
    refreshDataCounters();
    persistWorkspaceData();
    currentTab='settingssystem';
    showToast('กู้คืนข้อมูลร้านสำเร็จ');
    render();
  }catch(error){
    console.error('กู้คืนข้อมูลร้านไม่สำเร็จ',error);
    showToast('กู้คืนข้อมูลไม่สำเร็จ กรุณาลองใหม่หรือติดต่อผู้ดูแล','danger');
    render();
  }
}

async function saveUserSettings(){
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const firstName=get('set_user_first'),lastName=get('set_user_last'),phone=get('set_user_phone');
  const saveBtn=document.getElementById('saveUserSettingsBtn');
  if(saveBtn) saveBtn.disabled=true;
  try{
    await callEdgeFunction('admin-users',{action:'self-update',firstName,lastName,phone});
  }catch(e){
    if(saveBtn) saveBtn.disabled=false;
    showToast(e.message||'บันทึกข้อมูลส่วนตัวไม่สำเร็จ');
    return;
  }
  if(saveBtn) saveBtn.disabled=false;
  Object.assign(currentUserProfile,{firstName,lastName,phone});
  if(currentProfile) Object.assign(currentProfile,{firstName,lastName,phone});
  systemUsersLoaded=false; // owner's own row may be shown in ผู้ใช้งานในระบบ, refresh on next visit
  showToast('บันทึกข้อมูลส่วนตัวแล้ว'); render();
}

async function saveSystemUser(){
  if(loggedInUser()?.owner!==true){ showToast('เฉพาะเจ้าของร้านเท่านั้นที่สามารถจัดการผู้ใช้งานได้'); return; }
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const username=get('new_user_id'),firstName=get('new_user_first'),password=get('new_user_password'),passwordConfirm=get('new_user_password_confirm');
  const editingUser=editingSystemUserId!==null?systemUsers.find(user=>String(user.id)===String(editingSystemUserId)):null;
  if(!username){ showToast('กรุณากรอก ID ผู้ใช้งาน'); document.getElementById('new_user_id').focus(); return; }
  if(!/^[A-Za-z0-9._-]+$/.test(username)){ showToast('ID ใช้ได้เฉพาะตัวอักษรอังกฤษ ตัวเลข จุด ขีดกลาง และขีดล่าง'); document.getElementById('new_user_id').focus(); return; }
  if(!editingUser&&(password.length<10||!/[A-Za-z]/.test(password)||!/\d/.test(password))){ showToast('รหัสผ่านต้องมีอย่างน้อย 10 ตัวอักษร และมีทั้งตัวอักษรกับตัวเลข'); document.getElementById('new_user_password').focus(); return; }
  if(editingUser&&password&&(password.length<10||!/[A-Za-z]/.test(password)||!/\d/.test(password))){ showToast('รหัสผ่านใหม่ต้องมีอย่างน้อย 10 ตัวอักษร และมีทั้งตัวอักษรกับตัวเลข'); document.getElementById('new_user_password').focus(); return; }
  if(password!==passwordConfirm){ showToast('รหัสผ่านและการยืนยันไม่ตรงกัน'); document.getElementById('new_user_password_confirm').focus(); return; }
  if(!firstName){ showToast('กรุณากรอกชื่อผู้ใช้งาน'); document.getElementById('new_user_first').focus(); return; }
  if(!editingUser&&systemUsers.some(u=>String(u.username||'').toLowerCase()===username.toLowerCase())){ showToast('ID นี้มีอยู่ในระบบแล้ว'); return; }
  const requestedLevel=Number(get('new_user_level'))||2;
  const level=editingUser?.owner?1:Math.min(4,Math.max(2,requestedLevel));
  const phone=get('new_user_phone'),note=get('new_user_note');
  const warehouseIds=[...new Set([...document.querySelectorAll('[data-system-user-warehouse]:checked')].map(input=>Number(input.value)).filter(id=>Number.isInteger(id)&&id>0))];
  if(!editingUser?.owner&&warehouseIds.length===0){ showToast('กรุณาเลือกคลังสินค้าอย่างน้อย 1 คลัง'); document.querySelector('[data-system-user-warehouse]')?.focus(); return; }
  const pagePermissions=editingUser?.owner?[]:[...document.querySelectorAll('[data-system-user-permission-row]')].map(row=>{
    const getAction=action=>row.querySelector(`[data-permission-action="${action}"]`)?.checked===true;
    return {pageKey:String(row.dataset.systemUserPermissionRow||''),warehouseId:null,canView:getAction('canView'),canCreate:getAction('canCreate'),canEdit:getAction('canEdit'),canDelete:getAction('canDelete'),canPrint:getAction('canPrint'),canExport:getAction('canExport')};
  }).filter(permission=>permission.pageKey&&permission.canView);
  if(!editingUser?.owner&&!pagePermissions.some(permission=>permission.pageKey==='dashboard')){ showToast('กรุณาอนุญาตหน้า “ภาพรวม” อย่างน้อย 1 หน้า'); document.querySelector('[data-system-user-permission-row="dashboard"]')?.scrollIntoView({behavior:'smooth',block:'center'}); return; }
  const saveBtn=document.getElementById('saveSystemUserBtn');
  if(saveBtn) saveBtn.disabled=true;
  try{
    if(editingUser){
      await callEdgeFunction('admin-users',{action:'update',id:editingUser.id,password:password||undefined,firstName,phone,note,level,warehouseIds,pagePermissions});
      if(editingUser.owner) Object.assign(currentUserProfile,{firstName,phone});
    }else{
      await callEdgeFunction('admin-users',{action:'create',username,password,firstName,phone,note,level,warehouseIds,pagePermissions});
    }
  }catch(e){
    if(saveBtn) saveBtn.disabled=false;
    showToast(e.message||'บันทึกผู้ใช้งานไม่สำเร็จ');
    return;
  }
  if(saveBtn) saveBtn.disabled=false;
  persistWorkspaceData();
  const message=editingUser?`แก้ไขผู้ใช้งาน "${username}" แล้ว`:`เพิ่มผู้ใช้งาน "${username}" แล้ว`;
  addingSystemUser=false; editingSystemUserId=null; systemUsersLoaded=false; showToast(message); render();
}

async function deleteSystemUser(id){
  if(loggedInUser()?.owner!==true){ showToast('เฉพาะเจ้าของร้านเท่านั้นที่สามารถลบผู้ใช้งานได้'); return; }
  const user=systemUsers.find(item=>String(item.id)===String(id));
  if(!user) return;
  if(user.owner){ showToast('ไม่สามารถลบผู้ใช้งานหลักของระบบได้'); return; }
  if(!confirm(`ยืนยันลบผู้ใช้งาน "${user.firstName}" (ID: ${user.username}) ออกจากระบบ?`)) return;
  try{
    await callEdgeFunction('admin-users',{action:'delete',id});
  }catch(e){
    showToast(e.message||'ลบผู้ใช้งานไม่สำเร็จ');
    return;
  }
  systemUsersLoaded=false;
  showToast(`ลบผู้ใช้งาน "${user.username}" แล้ว`);
  render();
}

function saveSalesRepresentative(){
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const name=get('sr_name');
  if(!name){ showToast('กรุณากรอกชื่อผู้แทน'); document.getElementById('sr_name').focus(); return; }
  const code=get('sr_code');
  if(code){
    const duplicate=salesRepresentatives.find(rep=>rep.id!==editingSalesRepresentativeId&&String(rep.code||'').trim().toLowerCase()===code.toLowerCase());
    if(duplicate){ showToast(`รหัสผู้ติดต่อ "${code}" ถูกใช้แล้วโดย "${duplicate.name}"`); document.getElementById('sr_code').focus(); return; }
  }
  const data={code,name,phone:get('sr_phone'),line:get('sr_line'),company:get('sr_company'),note:get('sr_note')};
  if(editingSalesRepresentativeId==='new'){
    salesRepresentatives.push({id:nextSalesRepresentativeId++,...data});
    showToast(`เพิ่มรายชื่อผู้แทน “${name}” แล้ว`);
  }else{
    const rep=salesRepresentatives.find(x=>x.id===editingSalesRepresentativeId);
    if(rep){
      const oldName=rep.name;
      Object.assign(rep,data);
      purchaseOrders.forEach(doc=>{ if(doc.supplier===oldName) doc.supplier=name; });
      if(poDraft?.supplier===oldName) poDraft.supplier=name;
    }
    showToast(`บันทึกรายชื่อผู้แทน “${name}” แล้ว`);
  }
  editingSalesRepresentativeId=null;
  persistWorkspaceData();
  render();
}

function deleteSalesRepresentative(id){
  const rep=salesRepresentatives.find(x=>x.id===id); if(!rep) return;
  if(!confirm(`ยืนยันลบรายชื่อผู้แทน "${rep.name}" ?`)) return;
  salesRepresentatives=salesRepresentatives.filter(x=>x.id!==id);
  persistWorkspaceData();
  showToast(`ลบรายชื่อผู้แทน "${rep.name}" แล้ว`);
  render();
}

// ===== ระบบโปรโมชั่น: ฟังก์ชันจัดการฟอร์ม =====
// ค้นหาสินค้าแบบพิมพ์ค้นหา (เหมือนช่องสแกน/ค้นหาสินค้าในเอกสารอื่น) สำหรับเลือกสินค้าเข้าโปรโมชั่น
function renderPromoProductResults(query){
  const box=document.getElementById('promoProductResults');
  if(!box) return;
  const q=String(query||'').trim();
  if(!q){ box.innerHTML=''; box.hidden=true; return; }
  const needle=q.toLowerCase();
  const matches=activeProducts().filter(p=>
    (p.name||'').toLowerCase().includes(needle) ||
    (p.sku||'').toLowerCase().includes(needle) ||
    (p.barcode||'').toLowerCase().includes(needle)
  ).slice(0,8);
  box.innerHTML=matches.length?matches.map(p=>
    `<button type="button" class="doc-scan-result" data-pid="${p.id}"><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.sku||'-')} · บาร์โค้ด ${escapeHtml(p.barcode||'-')}</small></span></button>`
  ).join(''):`<div class="doc-scan-empty">ไม่พบสินค้า "${escapeHtml(q)}"</div>`;
  box.hidden=false;
  box.querySelectorAll('.doc-scan-result').forEach(btn=>{
    btn.addEventListener('mousedown',e=>e.preventDefault());
    btn.addEventListener('click',()=>selectPromoProduct(Number(btn.dataset.pid)));
  });
}
function selectPromoProduct(productId){
  const p=products.find(x=>x.id===productId); if(!p) return;
  const hidden=document.getElementById('promo_product_id');
  const searchInput=document.getElementById('promo_product_search');
  const box=document.getElementById('promoProductResults');
  if(hidden) hidden.value=p.id;
  if(searchInput) searchInput.value=p.name;
  if(box){ box.innerHTML=''; box.hidden=true; }
  updatePromoUnitOptions();
  // อัปเดตข้อความ "เลือกแล้ว: ..." โดยไม่ต้อง render ทั้งฟอร์มใหม่ (กันเสีย focus)
  const fieldWrap=document.getElementById('promo_product_field_wrap');
  if(fieldWrap){
    let hint=fieldWrap.querySelector('.promo-selected-hint');
    if(!hint){ hint=document.createElement('div'); hint.className='promo-selected-hint'; hint.style.cssText='font-size:12px;color:var(--text-muted);margin-top:6px;'; fieldWrap.appendChild(hint); }
    hint.innerHTML=`เลือกแล้ว: <b style="color:var(--text);">${escapeHtml(p.name)}</b> (${escapeHtml(p.sku||'-')})`;
  }
}
function bindPromoProductSearch(){
  const input=document.getElementById('promo_product_search');
  const box=document.getElementById('promoProductResults');
  if(!input||!box) return;
  input.addEventListener('input',()=>{
    // ถ้าผู้ใช้แก้ข้อความ ให้ล้างค่าที่เลือกไว้เดิม (ป้องกันเก็บ pid เก่ากับชื่อใหม่ไม่ตรงกัน)
    const hidden=document.getElementById('promo_product_id');
    if(hidden) hidden.value='';
    renderPromoProductResults(input.value);
  });
  input.addEventListener('focus',()=>{ if(input.value.trim()) renderPromoProductResults(input.value); });
  input.addEventListener('keydown',e=>{
    if(e.key==='Escape'){ box.hidden=true; return; }
    if(e.key!=='Enter') return;
    e.preventDefault();
    const query=input.value.trim(); if(!query) return;
    const exact=activeProducts().find(p=>(p.barcode||'').toLowerCase()===query.toLowerCase()||(p.sku||'').toLowerCase()===query.toLowerCase());
    if(exact){ selectPromoProduct(exact.id); return; }
    const needle=query.toLowerCase();
    const first=activeProducts().find(p=>(p.name||'').toLowerCase().includes(needle));
    if(first) selectPromoProduct(first.id);
  });
  input.addEventListener('blur',()=>setTimeout(()=>{ box.hidden=true; },140));
}
// ===== ค้นหาสินค้าคู่ (buy/get) สำหรับโปรฯ "ซื้อสินค้าหนึ่ง แถมอีกสินค้าหนึ่ง" (scope='buygetdiff') แยกจากช่องค้นหาสินค้ารายตัวเดิมทั้งหมด =====
const PROMO_BGD_FIELD_CONFIG={
  buy:{searchId:'promo_bgd_buy_product_search',hiddenId:'promo_bgd_buy_product_id',resultsId:'promoBgdBuyProductResults',wrapId:'promo_bgd_buy_field_wrap',unitSelectId:'promo_bgd_buy_unit'},
  get:{searchId:'promo_bgd_get_product_search',hiddenId:'promo_bgd_get_product_id',resultsId:'promoBgdGetProductResults',wrapId:'promo_bgd_get_field_wrap',unitSelectId:'promo_bgd_get_unit'},
};
function renderPromoBgdProductResults(which,query){
  const cfg=PROMO_BGD_FIELD_CONFIG[which]; if(!cfg) return;
  const box=document.getElementById(cfg.resultsId);
  if(!box) return;
  const q=String(query||'').trim();
  if(!q){ box.innerHTML=''; box.hidden=true; return; }
  const needle=q.toLowerCase();
  const matches=activeProducts().filter(p=>
    (p.name||'').toLowerCase().includes(needle) ||
    (p.sku||'').toLowerCase().includes(needle) ||
    (p.barcode||'').toLowerCase().includes(needle)
  ).slice(0,8);
  box.innerHTML=matches.length?matches.map(p=>
    `<button type="button" class="doc-scan-result" data-pid="${p.id}"><span><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.sku||'-')} · บาร์โค้ด ${escapeHtml(p.barcode||'-')}</small></span></button>`
  ).join(''):`<div class="doc-scan-empty">ไม่พบสินค้า "${escapeHtml(q)}"</div>`;
  box.hidden=false;
  box.querySelectorAll('.doc-scan-result').forEach(btn=>{
    btn.addEventListener('mousedown',e=>e.preventDefault());
    btn.addEventListener('click',()=>selectPromoBgdProduct(which,Number(btn.dataset.pid)));
  });
}
function selectPromoBgdProduct(which,productId){
  const cfg=PROMO_BGD_FIELD_CONFIG[which]; if(!cfg) return;
  const p=products.find(x=>x.id===productId); if(!p) return;
  const hidden=document.getElementById(cfg.hiddenId);
  const searchInput=document.getElementById(cfg.searchId);
  const box=document.getElementById(cfg.resultsId);
  if(hidden) hidden.value=p.id;
  if(searchInput) searchInput.value=p.name;
  if(box){ box.innerHTML=''; box.hidden=true; }
  updatePromoBgdUnitOptions(which);
  const fieldWrap=document.getElementById(cfg.wrapId);
  if(fieldWrap){
    let hint=fieldWrap.querySelector('.promo-selected-hint');
    if(!hint){ hint=document.createElement('div'); hint.className='promo-selected-hint'; hint.style.cssText='font-size:12px;color:var(--text-muted);margin-top:6px;'; fieldWrap.appendChild(hint); }
    hint.innerHTML=`เลือกแล้ว: <b style="color:var(--text);">${escapeHtml(p.name)}</b> (${escapeHtml(p.sku||'-')})`;
  }
}
function bindPromoBgdProductSearch(which){
  const cfg=PROMO_BGD_FIELD_CONFIG[which]; if(!cfg) return;
  const input=document.getElementById(cfg.searchId);
  const box=document.getElementById(cfg.resultsId);
  if(!input||!box) return;
  input.addEventListener('input',()=>{
    const hidden=document.getElementById(cfg.hiddenId);
    if(hidden) hidden.value='';
    renderPromoBgdProductResults(which,input.value);
  });
  input.addEventListener('focus',()=>{ if(input.value.trim()) renderPromoBgdProductResults(which,input.value); });
  input.addEventListener('keydown',e=>{
    if(e.key==='Escape'){ box.hidden=true; return; }
    if(e.key!=='Enter') return;
    e.preventDefault();
    const query=input.value.trim(); if(!query) return;
    const exact=activeProducts().find(p=>(p.barcode||'').toLowerCase()===query.toLowerCase()||(p.sku||'').toLowerCase()===query.toLowerCase());
    if(exact){ selectPromoBgdProduct(which,exact.id); return; }
    const needle=query.toLowerCase();
    const first=activeProducts().find(p=>(p.name||'').toLowerCase().includes(needle));
    if(first) selectPromoBgdProduct(which,first.id);
  });
  input.addEventListener('blur',()=>setTimeout(()=>{ box.hidden=true; },140));
}
function updatePromoBgdUnitOptions(which){
  const cfg=PROMO_BGD_FIELD_CONFIG[which]; if(!cfg) return;
  const unitSelect=document.getElementById(cfg.unitSelectId); if(!unitSelect) return;
  const productId=Number(document.getElementById(cfg.hiddenId)?.value);
  const p=products.find(x=>x.id===productId);
  if(!p){ unitSelect.innerHTML='<option value="">เลือกสินค้าก่อน</option>'; return; }
  const opts=[p.unit,...(p.units||[]).map(u=>u.sub)];
  unitSelect.innerHTML=opts.map(u=>{
    const usedBy=findPromotionUsingSlot(productId,u,editingPromotionId);
    return usedBy?`<option value="${escapeHtml(u)}" disabled>${escapeHtml(u)} (ใช้ในโปรฯ "${escapeHtml(usedBy.name)}" แล้ว)</option>`:`<option value="${escapeHtml(u)}">${escapeHtml(u)}</option>`;
  }).join('');
  if(unitSelect.options.length && unitSelect.options[unitSelect.selectedIndex]?.disabled){
    const firstEnabled=Array.from(unitSelect.options).find(o=>!o.disabled);
    if(firstEnabled) unitSelect.value=firstEnabled.value;
  }
}
// อัปเดตตัวเลือกหน่วยในช่อง "สินค้ารายตัว" ตามสินค้าที่เลือกไว้ - หน่วยที่ถูกใช้ในโปรฯ อื่นแล้วจะถูก disable
function updatePromoUnitOptions(){
  const unitSelect=document.getElementById('promo_unit'); if(!unitSelect) return;
  const productId=Number(document.getElementById('promo_product_id')?.value);
  const p=products.find(x=>x.id===productId);
  if(!p){ unitSelect.innerHTML='<option value="">เลือกสินค้าก่อน</option>'; return; }
  const opts=[p.unit,...(p.units||[]).map(u=>u.sub)];
  unitSelect.innerHTML=opts.map(u=>{
    const usedBy=findPromotionUsingSlot(productId,u,editingPromotionId);
    return usedBy?`<option value="${escapeHtml(u)}" disabled>${escapeHtml(u)} (ใช้ในโปรฯ "${escapeHtml(usedBy.name)}" แล้ว)</option>`:`<option value="${escapeHtml(u)}">${escapeHtml(u)}</option>`;
  }).join('');
  // ถ้าตัวเลือกแรกโดน disable ให้เลื่อนไปเลือกตัวแรกที่ยังว่างอยู่แทน (กันเลือก option disabled โดยไม่ตั้งใจ)
  if(unitSelect.options.length && unitSelect.options[unitSelect.selectedIndex]?.disabled){
    const firstEnabled=Array.from(unitSelect.options).find(o=>!o.disabled);
    if(firstEnabled) unitSelect.value=firstEnabled.value;
  }
}
// สลับว่าจะโชว์ช่องหน่วยแบบไหน: สินค้ารายตัว (unit เดียว) / เจาะจงสินค้า (หน่วยแยกต่อรายการ ไม่โชว์ช่องนี้)
function updatePromoUnitFieldVisibility(){
  const scopeEl=document.querySelector('input[name="promo_scope"]:checked');
  const scope=scopeEl?scopeEl.value:'product';
  const productUnitWrap=document.getElementById('promo_scope_product_unit');
  if(productUnitWrap) productUnitWrap.style.display=(scope==='product')?'block':'none';
  if(scope==='product') updatePromoUnitOptions();
}
// ดึงสินค้าตามหมวดหมู่/แบรนด์ที่เลือกไว้ สำหรับ modal เลือกสินค้า
function promoCategoryItemPool(){
  const category=document.getElementById('promo_category')?.value||'';
  const brand=document.getElementById('promo_brand')?.value||'';
  return activeProducts().filter(p=>{
    const productCategory=String(p.category||'').trim()||'ไม่ทราบหมวดหมู่';
    if(category && productCategory!==category) return false;
    if(brand && (p.brand||'ทั่วไป')!==brand) return false;
    return true;
  });
}
// เปิด modal เลือกสินค้าแบบติ๊กหลายตัว (checkbox) จากหมวดหมู่/แบรนด์ที่เลือกไว้
function openPromoItemPicker(){
  const category=document.getElementById('promo_category')?.value||'';
  if(!category){ showToast('กรุณาเลือกหมวดหมู่ก่อน'); return; }
  const brand=document.getElementById('promo_brand')?.value||'';
  const pool=promoCategoryItemPool();
  const alreadySelected=new Set((currentPromoDraftItems||[]).map(it=>it.productId));
  const checkedIds=new Set(alreadySelected);
  const overlay=document.createElement('div'); overlay.className='modal-overlay';
  overlay.innerHTML=`<div class="modal promo-item-picker-modal">
    <div class="modal-head"><h3>เลือกสินค้าในหมวดนี้</h3><button class="modal-close" aria-label="ปิด">×</button></div>
    <div class="promo-picker-sub">${escapeHtml(category)}${brand?` › ${escapeHtml(brand)}`:''} · พบ ${pool.length} รายการ</div>
    <div class="promo-picker-toolbar"><button type="button" class="btn ghost small" id="promoPickAllBtn">เลือกทั้งหมด</button><button type="button" class="btn ghost small" id="promoPickNoneBtn">ไม่เลือกเลย</button></div>
    <div class="promo-picker-list" id="promoPickerList">${pool.map(p=>`<label class="promo-picker-row"><input type="checkbox" data-pid="${p.id}" ${checkedIds.has(p.id)?'checked':''}><span>${escapeHtml(p.name)}</span></label>`).join('')||'<div class="promo-picker-empty">ไม่พบสินค้าในหมวด/แบรนด์นี้</div>'}</div>
    <div class="promo-picker-actions"><button type="button" class="btn ghost" id="promoPickerCancelBtn">ยกเลิก</button><button type="button" class="btn primary" id="promoPickerAddBtn">เพิ่มที่เลือก</button></div>
  </div>`;
  document.body.appendChild(overlay);
  const close=()=>overlay.remove();
  overlay.querySelector('.modal-close').onclick=close;
  overlay.querySelector('#promoPickerCancelBtn').onclick=close;
  overlay.querySelector('#promoPickAllBtn').onclick=()=>overlay.querySelectorAll('.promo-picker-row input[type="checkbox"]').forEach(cb=>cb.checked=true);
  overlay.querySelector('#promoPickNoneBtn').onclick=()=>overlay.querySelectorAll('.promo-picker-row input[type="checkbox"]').forEach(cb=>cb.checked=false);
  overlay.querySelector('#promoPickerAddBtn').onclick=()=>{
    const checked=Array.from(overlay.querySelectorAll('.promo-picker-row input[type="checkbox"]:checked')).map(cb=>Number(cb.dataset.pid));
    if(!currentPromoDraftItems) currentPromoDraftItems=[];
    checked.forEach(pid=>{
      if(currentPromoDraftItems.some(it=>it.productId===pid)) return;
      const p=products.find(x=>x.id===pid); if(!p) return;
      const unitOpts=[p.unit,...(p.units||[]).map(u=>u.sub)];
      const freeUnit=unitOpts.find(u=>!findPromotionUsingSlot(pid,u,editingPromotionId));
      currentPromoDraftItems.push({productId:pid,unit:freeUnit||p.unit});
    });
    // เอาตัวที่ถูกยกเลิกติ๊กออกจากรายการที่เลือกไว้เดิมด้วย (เฉพาะที่อยู่ในหมวด/แบรนด์นี้)
    const poolIds=new Set(pool.map(p=>p.id));
    const stillChecked=new Set(checked);
    currentPromoDraftItems=currentPromoDraftItems.filter(it=>!poolIds.has(it.productId)||stillChecked.has(it.productId));
    const listWrap=document.getElementById('promoCategoryItemsList');
    if(listWrap){ listWrap.innerHTML=renderPromoCategoryItemsList(currentPromoDraftItems); bindPromoCategoryItemListEvents(); }
    close();
  };
}
function bindPromoCategoryItemListEvents(){
  document.querySelectorAll('.promo-item-unit').forEach(sel=>{
    sel.addEventListener('change',()=>{
      const idx=Number(sel.dataset.idx);
      if(currentPromoDraftItems&&currentPromoDraftItems[idx]) currentPromoDraftItems[idx].unit=sel.value;
    });
  });
  document.querySelectorAll('.promo-item-remove').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const idx=Number(btn.dataset.idx);
      if(!currentPromoDraftItems) return;
      currentPromoDraftItems.splice(idx,1);
      const listWrap=document.getElementById('promoCategoryItemsList');
      if(listWrap){ listWrap.innerHTML=renderPromoCategoryItemsList(currentPromoDraftItems); bindPromoCategoryItemListEvents(); }
    });
  });
}
function savePromotion(){
  const g=id=>document.getElementById(id);
  const name=(g('promo_name')?.value||'').trim();
  if(!name){ showToast('กรุณากรอกชื่อโปรโมชั่น'); g('promo_name')?.focus(); return; }
  const active=document.querySelector('input[name="promo_active"]:checked')?.value==='1';
  const startDate=dmyToISO(g('promo_start')?.value)||'';
  const endDate=dmyToISO(g('promo_end')?.value)||'';
  if(startDate && endDate && startDate>endDate){ showToast('วันเริ่มต้องมาก่อนวันสิ้นสุด'); return; }
  const type=document.querySelector('input[name="promo_type"]:checked')?.value||'discount';
  let scope='product', productId=null, category='', brand='', categoryMode='all', unit='', items=[];
  let bgdBuyProductId=null, bgdBuyUnit='', bgdBuyQty=0, bgdGetProductId=null, bgdGetUnit='', bgdGetQty=0;
  if(type==='buygetdiff'){
    scope='buygetdiff';
    bgdBuyProductId=Number(g('promo_bgd_buy_product_id')?.value)||null;
    if(!bgdBuyProductId){ showToast('กรุณาเลือกสินค้าที่ต้องซื้อ'); g('promo_bgd_buy_product_search')?.focus(); return; }
    bgdBuyUnit=(g('promo_bgd_buy_unit')?.value||'').trim();
    if(!bgdBuyUnit){ showToast('กรุณาเลือกหน่วยสินค้าที่ต้องซื้อ'); return; }
    bgdBuyQty=parseInt(g('promo_bgd_buy_qty')?.value)||0;
    if(bgdBuyQty<=0){ showToast('กรุณากรอกจำนวนที่ต้องซื้อให้ถูกต้อง'); return; }
    bgdGetProductId=Number(g('promo_bgd_get_product_id')?.value)||null;
    if(!bgdGetProductId){ showToast('กรุณาเลือกสินค้าที่จะแถม'); g('promo_bgd_get_product_search')?.focus(); return; }
    bgdGetUnit=(g('promo_bgd_get_unit')?.value||'').trim();
    if(!bgdGetUnit){ showToast('กรุณาเลือกหน่วยสินค้าที่จะแถม'); return; }
    bgdGetQty=parseInt(g('promo_bgd_get_qty')?.value)||0;
    if(bgdGetQty<=0){ showToast('กรุณากรอกจำนวนที่จะแถมให้ถูกต้อง'); return; }
  } else {
    scope=document.querySelector('input[name="promo_scope"]:checked')?.value||'product';
    if(scope==='product'){
      productId=Number(g('promo_product_id')?.value)||null;
      if(!productId){ showToast('กรุณาเลือกสินค้าจากผลการค้นหา'); g('promo_product_search')?.focus(); return; }
      unit=(g('promo_unit')?.value||'').trim();
      if(!unit){ showToast('กรุณาเลือกหน่วยที่ร่วมโปรโมชั่น'); return; }
    } else {
      category=(g('promo_category')?.value||'').trim();
      if(!category){ showToast('กรุณาเลือกหมวดหมู่'); return; }
      brand=(g('promo_brand')?.value||'').trim();
      categoryMode='select';
      items=(currentPromoDraftItems||[]).map(it=>({productId:it.productId,unit:it.unit}));
      if(items.length===0){ showToast('กรุณาเลือกสินค้าอย่างน้อย 1 รายการ'); return; }
    }
  }
  // ป้องกันสินค้า+หน่วยซ้ำกับโปรฯ อื่นที่เปิดใช้งานอยู่ (เช็คเฉพาะตอนโปรฯ นี้เปิดใช้งานด้วย เพราะโปรฯ ที่ปิดอยู่ไม่มีผลจริง)
  if(active){
    const slotsToCheck=type==='buygetdiff'?[{productId:bgdBuyProductId,unit:bgdBuyUnit},{productId:bgdGetProductId,unit:bgdGetUnit}]:(scope==='product'?[{productId,unit}]:items);
    for(const slot of slotsToCheck){
      const usedBy=findPromotionUsingSlot(slot.productId,slot.unit,editingPromotionId);
      if(usedBy){
        const p=products.find(x=>x.id===slot.productId);
        showToast(`${p?p.name:'สินค้า'} หน่วย ${slot.unit} ถูกใช้ในโปรโมชั่น "${usedBy.name}" อยู่แล้ว`);
        return;
      }
    }
  }
  const data={name,active,startDate,endDate,scope,productId,category,brand,categoryMode,items,unit,type,
    discountMode:'percent',discountValue:'',bundleQty:'',bundlePrice:'',
    bgdBuyProductId,bgdBuyUnit,bgdBuyQty,bgdGetProductId,bgdGetUnit,bgdGetQty};
  if(type==='discount'){
    data.discountMode=document.querySelector('input[name="promo_discount_mode"]:checked')?.value||'percent';
    data.discountValue=parseFloat(g('promo_discount_value')?.value)||0;
    if(data.discountValue<=0){ showToast('กรุณากรอกมูลค่าส่วนลดให้ถูกต้อง'); return; }
    if(data.discountMode==='percent' && data.discountValue>100){ showToast('ส่วนลดเป็น % ต้องไม่เกิน 100'); return; }
  } else if(type==='bundle'){
    data.bundleQty=parseInt(g('promo_bundle_qty')?.value)||0;
    data.bundlePrice=parseFloat(g('promo_bundle_price')?.value)||0;
    if(data.bundleQty<=1){ showToast('จำนวนที่ซื้อครบต้องมากกว่า 1 ชิ้น'); return; }
    if(data.bundlePrice<=0){ showToast('กรุณากรอกราคาพิเศษให้ถูกต้อง'); return; }
  }
  if(editingPromotionId==='new'){
    promotions.push({id:nextPromotionId++,...data});
    showToast(`สร้างโปรโมชั่น "${name}" แล้ว`);
  } else {
    Object.assign(promotions.find(x=>x.id===editingPromotionId),data);
    showToast(`บันทึกโปรโมชั่น "${name}" แล้ว`);
  }
  persistPromotions();
  editingPromotionId=null;
  promoDraftItemsSyncedFor=undefined;
  currentPromoDraftItems=null;
  render();
}
function deletePromotion(id){
  const promo=promotions.find(x=>x.id===id); if(!promo) return;
  if(!confirm(`ยืนยันลบโปรโมชั่น "${promo.name}" ?`)) return;
  promotions=promotions.filter(x=>x.id!==id);
  persistPromotions();
  showToast(`ลบโปรโมชั่น "${promo.name}" แล้ว`);
  render();
}

async function downloadContactImportTemplate(){
  try{ await ensureXlsxLoaded(); }catch(error){ console.warn('load xlsx',error); }
  const example=[{
    'รหัสผู้ติดต่อ':'C0001','ประเภทผู้ติดต่อ':'นิติบุคคล','ประเภท':'ลูกค้า','ชื่อธุรกิจ / ชื่อ':'บริษัท ตัวอย่าง จำกัด',
    'เลขผู้เสียภาษี':'0105551234567','เครดิต (วัน)':30,'ที่อยู่':'','รหัสไปรษณีย์':'',
    'ชื่อผู้ติดต่อ':'คุณตัวอย่าง','อีเมล':'','เบอร์มือถือ':'081-234-5678',
    'ธนาคาร':'','ชื่อบัญชี':'','เลขที่บัญชี':'','ประเภทบัญชี':'','โน๊ต':''
  }];
  if(window.XLSX){
    const sheet=XLSX.utils.json_to_sheet(example);
    sheet['!cols']=Object.keys(example[0]).map(header=>({wch:Math.max(14,Math.min(28,header.length+5))}));
    const workbook=XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook,sheet,'สมุดรายชื่อ');
    const instructions=[
      ['หัวข้อ','วิธีกรอก'],
      ['รหัสผู้ติดต่อ','ถ้ากรอกและตรงกับรายชื่อเดิมในระบบ จะอัปเดตรายชื่อนั้นแทนการสร้างใหม่ (เว้นว่างได้)'],
      ['ชื่อธุรกิจ / ชื่อ','จำเป็นต้องกรอก ถ้าไม่กรอกรหัสผู้ติดต่อ ระบบจะจับคู่จากชื่อที่ตรงกันเป๊ะแทน'],
      ['ประเภทผู้ติดต่อ','กรอก นิติบุคคล หรือ บุคคลธรรมดา (ไม่บังคับ ค่าเริ่มต้น นิติบุคคล)'],
      ['ประเภท','กรอก ลูกค้า, ผู้จำหน่าย หรือ ทั้งคู่ (ไม่บังคับ ค่าเริ่มต้น ลูกค้า)'],
      ['ประเภทบัญชี','กรอก ออมทรัพย์ หรือ กระแสรายวัน (ไม่บังคับ)'],
      ['ข้อสำคัญ','อย่าเปลี่ยนชื่อหัวคอลัมน์ในแถวแรก'],
    ];
    const instructionSheet=XLSX.utils.aoa_to_sheet(instructions);
    instructionSheet['!cols']=[{wch:20},{wch:80}];
    XLSX.utils.book_append_sheet(workbook,instructionSheet,'วิธีกรอก');
    XLSX.writeFile(workbook,'PEPOS-ตัวอย่างนำเข้าสมุดรายชื่อ.xlsx');
    return;
  }
  const headers=Object.keys(example[0]);
  const csv='\uFEFF'+headers.join(',')+'\n'+headers.map(key=>`"${String(example[0][key]).replace(/"/g,'""')}"`).join(',');
  const link=document.createElement('a');
  link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  link.download='PEPOS-ตัวอย่างนำเข้าสมุดรายชื่อ.csv';
  link.click();
  setTimeout(()=>URL.revokeObjectURL(link.href),1000);
}
function contactImportTypes(value){
  const text=String(value||'').trim().toLowerCase();
  const types=[];
  if(text.includes('ลูกค้า')||text.includes('customer')) types.push('customer');
  if(text.includes('จำหน่าย')||text.includes('supplier')||text.includes('vendor')) types.push('supplier');
  if(text.includes('ทั้งคู่')||text.includes('both')){ if(!types.includes('customer')) types.push('customer'); if(!types.includes('supplier')) types.push('supplier'); }
  return types.length?types:['customer'];
}
function contactImportEntity(value){
  const text=String(value||'').trim().toLowerCase();
  if(text.includes('บุคคลธรรมดา')||text.includes('individual')) return 'individual';
  return 'juristic';
}
function contactImportAccType(value){
  const text=String(value||'').trim().toLowerCase();
  if(text.includes('กระแส')||text.includes('current')) return 'current';
  if(text.includes('ออม')||text.includes('saving')) return 'saving';
  return '';
}
async function importContactsFromExcel(file){
  try{ await ensureXlsxLoaded(); }catch(error){ showToast(error.message||'ไม่สามารถโหลดระบบอ่าน Excel ได้ กรุณาเชื่อมต่ออินเทอร์เน็ตแล้วลองใหม่'); return; }
  let workbook;
  try{ workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false}); }
  catch(error){ showToast('ไม่สามารถอ่านไฟล์ Excel นี้ได้'); return; }
  const firstSheet=workbook.Sheets[workbook.SheetNames[0]];
  const sourceRows=XLSX.utils.sheet_to_json(firstSheet,{defval:'',raw:true});
  if(!sourceRows.length){ showToast('ไม่พบข้อมูลในไฟล์'); return; }

  const toCreate=[];
  const toUpdate=[];
  const skipped=[];
  const seenInFile=new Set(); // guard against two rows in the same file matching the same existing contact

  sourceRows.forEach((row,index)=>{
    const line=index+2;
    const name=String(productImportValue(row,['ชื่อธุรกิจ / ชื่อ','ชื่อธุรกิจ','ชื่อ','รายชื่อ','name'])).trim();
    if(!name){ skipped.push(`แถว ${line}: ไม่มีชื่อธุรกิจ / ชื่อ`); return; }
    const code=String(productImportValue(row,['รหัสผู้ติดต่อ','รหัส','code'])).trim();
    const data={
      name,
      types:contactImportTypes(productImportValue(row,['ประเภท','type'])),
      entity:contactImportEntity(productImportValue(row,['ประเภทผู้ติดต่อ','entity'])),
      code,
      taxId:String(productImportValue(row,['เลขผู้เสียภาษี','taxid'])).trim(),
      creditDays:productImportNumber(productImportValue(row,['เครดิต (วัน)','เครดิต','creditdays']),'')||'',
      address:String(productImportValue(row,['ที่อยู่','address'])).trim(),
      postcode:String(productImportValue(row,['รหัสไปรษณีย์','postcode'])).trim(),
      contactName:String(productImportValue(row,['ชื่อผู้ติดต่อ','contactname'])).trim(),
      email:String(productImportValue(row,['อีเมล','email'])).trim(),
      phone:String(productImportValue(row,['เบอร์มือถือ','เบอร์โทร','phone'])).trim(),
      bank:String(productImportValue(row,['ธนาคาร','bank'])).trim(),
      bankName:String(productImportValue(row,['ชื่อบัญชี','bankname'])).trim(),
      bankAcc:String(productImportValue(row,['เลขที่บัญชี','bankacc'])).trim(),
      accType:contactImportAccType(productImportValue(row,['ประเภทบัญชี','acctype'])),
      note:String(productImportValue(row,['โน๊ต','หมายเหตุ','note'])).trim(),
    };
    let existing=null;
    const systemId=productImportNumber(productImportValue(row,['รหัสอ้างอิงระบบ','systemid']),NaN);
    if(Number.isFinite(systemId)) existing=contacts.find(c=>c.id===systemId);
    if(!existing&&code) existing=contacts.find(c=>String(c.code||'').trim().toLowerCase()===code.toLowerCase());
    if(!existing) existing=contacts.find(c=>String(c.name||'').trim().toLowerCase()===name.toLowerCase());
    if(existing){
      if(seenInFile.has(existing.id)){ skipped.push(`แถว ${line}: ซ้ำกับแถวก่อนหน้าในไฟล์เดียวกัน (${name})`); return; }
      seenInFile.add(existing.id);
      toUpdate.push({existing,data});
    }else{
      toCreate.push(data);
    }
  });

  if(!toCreate.length&&!toUpdate.length){
    alert(`ไม่สามารถนำเข้าข้อมูลได้\n\n${skipped.slice(0,8).join('\n')}${skipped.length>8?`\nและอีก ${skipped.length-8} รายการ`:''}`);
    return;
  }
  const confirmation=`พบข้อมูล ${sourceRows.length} แถว\nจะเพิ่มรายชื่อใหม่ ${toCreate.length} รายการ\nจะอัปเดตรายชื่อเดิม ${toUpdate.length} รายการ${skipped.length?`\nข้าม ${skipped.length} แถวที่ข้อมูลไม่ครบ`:''}\n\nยืนยันนำเข้าหรือไม่?`;
  if(!confirm(confirmation)) return;

  toUpdate.forEach(({existing,data})=>Object.assign(existing,data));
  toCreate.forEach(data=>contacts.push({id:nextContactId++,...data}));
  persistContacts();
  showToast(`นำเข้าสมุดรายชื่อสำเร็จ · เพิ่มใหม่ ${toCreate.length} · อัปเดต ${toUpdate.length}${skipped.length?` · ข้าม ${skipped.length}`:''}`);
  render();
}

async function exportContactsToExcel(){
  try{ await ensureXlsxLoaded(); }catch(error){ showToast(error.message||'ไม่สามารถโหลดระบบส่งออก Excel ได้ กรุณาเชื่อมต่ออินเทอร์เน็ตแล้วลองใหม่'); return; }
  if(!contacts.length){ showToast('ยังไม่มีข้อมูลให้ส่งออก'); return; }
  const typeLabel=c=>{ const isCust=c.types?.includes('customer'),isSupp=c.types?.includes('supplier'); if(isCust&&isSupp) return 'ทั้งคู่'; if(isSupp) return 'ผู้จำหน่าย'; return 'ลูกค้า'; };
  const rows=contacts.map(c=>({
    'รหัสอ้างอิงระบบ':c.id,
    'รหัสผู้ติดต่อ':c.code||'',
    'ประเภทผู้ติดต่อ':c.entity==='individual'?'บุคคลธรรมดา':'นิติบุคคล',
    'ประเภท':typeLabel(c),
    'ชื่อธุรกิจ / ชื่อ':c.name||'',
    'เลขผู้เสียภาษี':c.taxId||'',
    'เครดิต (วัน)':c.creditDays||'',
    'ที่อยู่':c.address||'',
    'รหัสไปรษณีย์':c.postcode||'',
    'ชื่อผู้ติดต่อ':c.contactName||'',
    'อีเมล':c.email||'',
    'เบอร์มือถือ':c.phone||'',
    'ธนาคาร':c.bank||'',
    'ชื่อบัญชี':c.bankName||'',
    'เลขที่บัญชี':c.bankAcc||'',
    'ประเภทบัญชี':c.accType==='current'?'กระแสรายวัน':(c.accType==='saving'?'ออมทรัพย์':''),
    'โน๊ต':c.note||'',
  }));
  const sheet=XLSX.utils.json_to_sheet(rows);
  sheet['!cols']=Object.keys(rows[0]).map(header=>({wch:Math.max(14,Math.min(28,header.length+5))}));
  const workbook=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook,sheet,'สมุดรายชื่อ');
  XLSX.writeFile(workbook,`PEPOS-สมุดรายชื่อ-${TODAY_STR}.xlsx`);
  showToast(`ส่งออกสมุดรายชื่อ ${rows.length} รายการแล้ว`);
}

async function createOwnerRecoveryCode(){
  if(loggedInUser()?.owner!==true) return;
  if(!confirm('สร้างรหัสกู้คืนใหม่หรือไม่? รหัสกู้คืนเดิมจะใช้ไม่ได้ทันที')) return;
  const button=document.getElementById('createOwnerRecoveryCodeBtn'); if(button) button.disabled=true;
  try{
    const result=await callEdgeFunction('admin-users',{action:'create-owner-recovery-code'});
    const content=`PEPOS - รหัสกู้คืน Password เจ้าของร้าน\nID เจ้าของร้าน: ${currentProfile?.username||''}\nรหัสกู้คืน: ${result.recoveryCode}\nใช้ได้ถึง: ${new Date(result.expiresAt).toLocaleString('th-TH')}\n\nเก็บไฟล์นี้ไว้ในพื้นที่ส่วนตัวแยกจากเครื่องขาย`;
    const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));
    const link=document.createElement('a'); link.href=url; link.download=`PEPOS-Recovery-${currentDateStr()}.txt`; link.click(); setTimeout(()=>URL.revokeObjectURL(url),1000);
    try{ await navigator.clipboard?.writeText(result.recoveryCode); }catch(_error){}
    prompt('ดาวน์โหลดไฟล์รหัสกู้คืนแล้ว และคัดลอกรหัสไว้ให้ด้วย กรุณาเก็บในที่ปลอดภัย',result.recoveryCode);
    showToast('สร้างรหัสกู้คืนใหม่แล้ว');
  }catch(error){ showToast(error?.message||'สร้างรหัสกู้คืนไม่สำเร็จ','danger'); }
  if(button) button.disabled=false;
}

async function recoverOwnerPassword(){
  const username=(prompt('กรอก ID เจ้าของร้าน')||'').trim(); if(!username) return;
  const recoveryCode=(prompt('กรอกรหัสกู้คืน 24 ตัว')||'').trim(); if(!recoveryCode) return;
  const password=prompt('กำหนด Password ใหม่ อย่างน้อย 10 ตัว มีตัวอักษรและตัวเลข')||''; if(!password) return;
  const confirmation=prompt('กรอก Password ใหม่อีกครั้ง')||'';
  if(password!==confirmation){ alert('Password ใหม่ทั้งสองครั้งไม่ตรงกัน'); return; }
  try{
    await callEdgeFunction('owner-recovery',{username,recoveryCode,password});
    const userInput=document.getElementById('loginUserId'),passwordInput=document.getElementById('loginPassword');
    if(userInput) userInput.value=username; if(passwordInput) passwordInput.value='';
    alert('ตั้ง Password ใหม่สำเร็จแล้ว กรุณาเข้าสู่ระบบ และสร้างรหัสกู้คืนชุดใหม่หลังเข้าสู่ระบบ');
    passwordInput?.focus();
  }catch(error){ alert(error?.message||'กู้คืน Password ไม่สำเร็จ'); }
}

